const moduleGuidance={
  accounts:[['本模块目的','确认需要纳入 Recovery Map 的重要交易所、DEX / DeFi、热钱包、冷钱包、多签钱包及其他 Crypto 账户，建立后续恢复工作的基础清单。'],['填写重点','请按照实际持有情况，选择需要纳入 Recovery Map 的平台或钱包。同一平台存在多个独立账户时，可分别添加并填写必要的账户识别信息。'],['填写建议','若资产长期分散在较多、低余额或很少使用的账户中，可根据自身安全、税务和实际使用需要，考虑适当整理和归纳。减少不必要的账户分散，有助于降低日常管理复杂度，也能让未来恢复路径更加清晰。'],['安全提醒','本模块只用于确认有哪些账户和钱包，请不要在这里直接填写完整助记词或私钥。'],['进一步帮助','如需了解更详细的填写方法，可在线查看本模块的填写示例及详细填写说明。']],
  conditions:[['本模块目的','确认每一个交易所账户或钱包在登录、恢复或重新取得控制权之前，需要准备的必要恢复条件和材料。'],['填写重点','不同账户类型的恢复方式和所需条件可能不同。请针对每一个已选择的平台或钱包，逐项确认其实际需要的恢复条件，并尽量做到无遗漏。'],['填写建议','请以账户当前真实设置和实际恢复方式为准。如不能确定某项条件是否真正需要，建议通过实际登录检查、恢复演练或平台 / 钱包官方资料进一步确认。'],['安全提醒','本模块用于确认“恢复需要什么”，请不要直接填写完整助记词或完整私钥。'],['进一步帮助','如需了解不同账户类型应该重点检查哪些恢复条件，可在线查看本模块的填写示例及详细填写说明。'],['文件与补充','完成本模块后，系统将根据你选择的平台、钱包及对应恢复条件，自动生成一份恢复条件汇总文档。']],
  locations:[['本模块目的','本模块用于记录 Module 2 已确认的恢复条件在哪里，以及未来如何找到和取得这些材料。'],['填写方式','<span class="guidance-step"><b>1｜优先使用汇总填写模板</b>如果需要记录多个平台或钱包的位置与查找信息，建议先使用汇总模板统一整理。</span><span class="guidance-step"><b>2｜单一平台模板作为补充</b>如果某个平台或钱包情况较复杂，需要单独说明更详细的位置、设备或查找路径，可以再下载对应的单一平台模板补充。汇总模板和单一平台模板可以同时使用。</span><span class="guidance-step"><b>3｜模板记录完整时，在线填写可以省略</b>如果相关信息已经在填写模板中完整记录，在线填写部分无需重复填写。如果只需记录或强调少量重点信息，也可以直接在线填写。</span><span class="guidance-step"><b>4｜还可以使用其他附件补充</b>如有必要，可以上传图片、语音、操作截图或其他文档，帮助未来恢复人更容易找到和理解对应材料。</span>'],['填写重点','请根据实际情况说明相关恢复条件的访问入口、相关设备和具体保存位置。'],['示例','注册邮箱：使用哪个邮箱服务、从哪里登录。2FA：位于哪台手机或备用设备。Seed Phrase：保存在什么具体位置。Hardware Wallet：设备保存在哪里。'],['填写建议','填写“保存位置”时应尽量具体，例如：书房保险柜、书桌左侧第二抽屉、备用手机、密码管理器中的 Binance Login 条目。不要只写“家里、电脑里、密码管理器、纸质资料、云端”。'],['更新提醒','当设备、文件、恢复材料或保存位置发生变化时，请及时更新本模块。']],
  instructions:[['本模块目的','本模块用于记录在找到所需恢复条件和材料之后，如何重新登录账户、恢复钱包或重新取得资产控制权。'],['填写方式','<span class="guidance-step"><b>1｜优先使用汇总填写模板</b>如果需要记录多个平台或钱包的恢复与转移步骤，建议先使用汇总模板统一整理。</span><span class="guidance-step"><b>2｜单一平台模板作为补充</b>如果某个平台或钱包的恢复过程较复杂，存在特殊设备状态、备用恢复路径或其他需要单独说明的情况，可以再使用对应的单一平台模板补充。汇总模板和单一平台模板可以同时使用。</span><span class="guidance-step"><b>3｜模板记录完整时，在线填写可以省略</b>如果恢复步骤已经在填写模板中完整记录，在线填写部分无需重复填写。如果只需记录少量重点步骤或特别提醒，也可以直接在线填写。</span><span class="guidance-step"><b>4｜还可以使用其他附件补充</b>如有必要，可以上传操作截图、图片、语音、视频或其他文档，帮助未来恢复人理解实际恢复过程。</span>'],['两种情况','建议分别考虑：1. 现有 / 备用设备仍可使用；2. 原有设备不可用，需要在新设备上重新恢复。'],['填写建议','一个步骤只写一个动作，按实际操作顺序填写，并写清楚完成这一步后应看到什么结果。不确定的步骤，建议先通过实际登录检查、轻量恢复演练或官方资料确认后再记录。'],['开始前确认','Module 2 的恢复条件已经完整；Module 3 的保存位置和查找路径已经明确。']],
  assistants:[['本模块说明','本模块用于记录未来恢复过程中可能提供帮助的人或机构，以及什么时候联系他们、他们可以协助什么。'],['可以记录谁','家庭成员、信任的人、律师、遗嘱执行人、受托人、会计师、税务或财富顾问、技术协助人、多签 Signer、公司或其他专业机构。'],['01｜协助人是谁','记录姓名或机构，以及其角色或与账户持有人的关系。'],['02｜什么时候联系','说明未来恢复人在什么情况下需要联系此人或机构。'],['03｜可以协助什么','说明可以提供的具体帮助，不要只写“可以帮忙”。'],['04｜身份与权限','如具有律师、Executor、Trustee、Signer、公司管理员等正式身份，可进行说明。'],['05｜已知或可协助查找的信息','说明其知道哪些信息、可以帮助找到哪些材料、设备或文件。'],['06｜替代联系人','如主要协助人无法联系，可以记录备用联系人或机构。'],['07｜及时更新','联系方式、角色、权限或可用性发生变化时，应及时更新。'],['必要提醒','被列为协助人，不代表拥有资产控制权；不建议任何一个协助人集中掌握全部控制材料；完整 Seed Phrase / 助记词和完整 Private Key / 私钥不应交给任何协助人。'],['附件补充','如果文字不足，可使用文字文件、图片、文档、语音留言等附件补充。如果不需要协助人，可以明确选择“不需要”。']],
  message:[['本模块说明','本模块用于留下前面几个模块无法完整表达的重要提醒、个人安排，以及你真正想对未来恢复人说的话。'],['表达方式','你可以说明需要特别注意的事情和特殊背景，也可以留下你对财富、家庭、责任和人生的理解。这里没有标准答案，也不要求全部填写。你可以只留下几句话，也可以通过文字、图片、照片、语音留言或视频留下更完整的表达。'],['特别说明','有些财富可以被转移，有些价值只能被传递。除了帮助未来恢复人理解这些资产，也可以让他们理解你为什么这样安排，以及你真正希望留下什么。'],['01｜重要提醒与特殊安排','记录前面模块难以表达、但未来恢复人确实需要知道的重点。'],['02｜关于这些资产与财富，我想留下的想法','可以写这些资产为什么重要、你如何理解财富，以及你希望它们未来发挥什么价值。'],['03｜我最想对你说的话','可以是一段话、一封信，或任何真正希望未来恢复人、家人或重要的人看到的内容。'],['04｜留下文字，也可以留下声音和影像','如文字不足，可以通过图片、照片、语音留言或视频补充。留下的不只是信息，也可以是你的声音。'],['05｜更新与确认','当重要安排、账户状态或附件发生变化后，请及时更新相关内容。'],['安全边界','不要在本模块直接写入完整 Seed Phrase / 助记词、Private Key / 私钥、OTP、Authenticator Seed 或完整密码。如涉及最终资产归属、遗嘱、信托或其他法律分配事项，以正式生效的法律文件为准。']]
};
const guidanceTopic=([title,body],extra='')=>`<section class="module-guidance-topic${extra?` ${extra}`:''}${/提醒|附件|补充|安全边界/.test(title)?' auxiliary':''}"><h3>${title}</h3><div>${body}</div></section>`;
const guidanceSequence=items=>`<div class="module-guidance-sequence">${items.map(guidanceTopic).join('')}</div>`;
const guidanceSteps=body=>guidanceSequence([...body.matchAll(/<span class="guidance-step"><b>\d+｜([^<]+)<\/b>([\s\S]*?)<\/span>/g)].map((match,index)=>[`${String(index+1).padStart(2,'0')}｜${match[1]}`,match[2]]));
function instructionPanel(moduleId){const guidance=moduleGuidance[moduleId];if(guidance){if(moduleId==='accounts'){return`<details class="module-instructions module-instructions-linear"><summary>填写说明</summary><div>${guidanceTopic(['A｜本模块说明',guidance[0][1]])}${guidanceTopic(['B｜填写重点',guidanceSequence([['01｜选择与识别',guidance[1][1]],['02｜整理建议',guidance[2][1]]])])}${guidanceTopic(['C｜安全边界',guidance[3][1]],'auxiliary')}${guidanceTopic(['D｜进一步帮助',guidance[4][1]],'auxiliary')}</div></details>`;}if(moduleId==='conditions'){return`<details class="module-instructions module-instructions-linear"><summary>填写说明</summary><div>${guidanceTopic(['A｜本模块说明',guidance[0][1]])}${guidanceTopic(['B｜需要确认什么',guidanceSequence([['01｜逐项确认',guidance[1][1]],['02｜确认方法',guidance[2][1]]])])}${guidanceTopic(['C｜安全边界',guidance[3][1]],'auxiliary')}${guidanceTopic(['D｜文件与补充',`${guidance[4][1]} ${guidance[5][1]}`],'auxiliary')}</div></details>`;}if(moduleId==='locations'){const columns=[[guidanceTopic(['A｜本模块说明',guidance[0][1]]),guidanceTopic(['B｜填写重点',guidanceSequence([['01｜需要记录什么',guidance[2][1]],['02｜填写建议',guidance[4][1]]])]),guidanceTopic(['C｜示例与更新',guidanceSequence([['01｜示例',guidance[3][1]],['02｜更新提醒',guidance[5][1]]])])],[guidanceTopic(['D｜填写方式',guidance[1][1]])]];return`<details class="module-instructions module-instructions-independent"><summary>填写说明</summary><div>${columns.map((items,index)=>`<div class="module-guidance-column" data-guidance-column="${index?'right':'left'}">${items.join('')}</div>`).join('')}</div></details>`;}if(moduleId==='instructions'){const columns=[[guidanceTopic(['A｜本模块说明',guidance[0][1]]),guidanceTopic(['B｜开始前准备',guidanceSequence([['01｜两种情况',guidance[2][1]],['02｜开始前确认',guidance[4][1]],['03｜填写建议',guidance[3][1]]])])],[guidanceTopic(['C｜填写方式',guidance[1][1]])]];return`<details class="module-instructions module-instructions-independent"><summary>填写说明</summary><div>${columns.map((items,index)=>`<div class="module-guidance-column" data-guidance-column="${index?'right':'left'}">${items.join('')}</div>`).join('')}</div></details>`;}if(moduleId==='assistants'){const intro=[guidance[0][1],guidance[1][1]].join(' '),items=guidance.slice(2,9);return`<details class="module-instructions module-instructions-linear"><summary>填写说明</summary><div>${guidanceTopic(['A｜本模块说明',intro])}${guidanceTopic(['B｜需要记录哪些信息',guidanceSequence(items)])}${guidanceTopic(['C｜必要提醒',guidance[9][1]],'auxiliary')}${guidanceTopic(['D｜附件补充',guidance[10][1]],'auxiliary')}</div></details>`;}if(moduleId==='message'){const expression=`${guidance[1][1]} ${guidance[2][1]}`,items=guidance.slice(3,8);return`<details class="module-instructions module-instructions-linear"><summary>填写说明</summary><div>${guidanceTopic(['A｜本模块说明',guidance[0][1]])}${guidanceTopic(['B｜表达方式',expression])}${guidanceTopic(['C｜可以写些什么',guidanceSequence(items)])}${guidanceTopic(['D｜安全边界',guidance[8][1]],'auxiliary')}${guidanceTopic(['E｜附件补充','如文字不足，可以使用文字文件、图片、照片、文档、语音留言或视频补充。'],'auxiliary')}</div></details>`;}return`<details class="module-instructions"><summary>填写说明</summary><div>${guidance.map(item=>guidanceTopic(item)).join('')}</div></details>`;}const items=moduleInstructions[moduleId]??[];return`<details class="module-instructions"><summary>填写说明</summary><div>${[['为什么',items[0]],['应该记录',items[1]],['不要记录',items[2]],['必填与选填',items[3]],['文字与附件',items[4]],['附件汇总','你可以上传一个或多个“本模块汇总信息”附件；也可以选择具体账户，分别上传补充材料。'],['简单示例',items[5]],['未来如何使用',items[6]]].map(item=>guidanceTopic(item)).join('')}</div></details>`;}
function unifiedInstructionPanel(moduleId){const guidance=moduleGuidance[moduleId];if(moduleId==='locations'){const columns=[[guidanceTopic(['A｜本模块说明',guidance[0][1]]),guidanceTopic(['B｜填写重点与建议',guidanceSequence([['01｜填写重点',guidance[2][1]],['02｜填写建议',guidance[4][1]],['03｜示例',guidance[3][1]],['04｜更新提醒',guidance[5][1]]])])],[guidanceTopic(['C｜填写方式',guidanceSteps(guidance[1][1])])]];return`<details class="module-instructions module-instructions-independent"><summary>填写说明</summary><div>${columns.map((items,index)=>`<div class="module-guidance-column" data-guidance-column="${index?'right':'left'}">${items.join('')}</div>`).join('')}</div></details>`;}if(moduleId==='instructions'){const columns=[[guidanceTopic(['A｜本模块说明',guidance[0][1]]),guidanceTopic(['B｜开始前准备',guidanceSequence([['01｜两种情况',guidance[2][1]],['02｜开始前确认',guidance[4][1]],['03｜填写建议',guidance[3][1]]])])],[guidanceTopic(['C｜填写方式',guidanceSteps(guidance[1][1])])]];return`<details class="module-instructions module-instructions-independent"><summary>填写说明</summary><div>${columns.map((items,index)=>`<div class="module-guidance-column" data-guidance-column="${index?'right':'left'}">${items.join('')}</div>`).join('')}</div></details>`;}return instructionPanel(moduleId);}
const baseInstructionPanel=instructionPanel;
instructionPanel=moduleId=>['locations','instructions'].includes(moduleId)?unifiedInstructionPanel(moduleId):baseInstructionPanel(moduleId);
const dualBaselineInstructionPanel=instructionPanel;
const guidanceColumns=columns=>`<details class="module-instructions module-instructions-independent"><summary>填写说明</summary><div>${columns.map((items,index)=>`<div class="module-guidance-column" data-guidance-column="${index?'right':'left'}">${items.join('')}</div>`).join('')}</div></details>`;
const guidanceSequenceWide=items=>`<div class="module-guidance-sequence module-guidance-sequence-wide">${items.map(guidanceTopic).join('')}</div>`;
function standardizedInstructionPanel(moduleId){const guidance=moduleGuidance[moduleId];if(moduleId==='accounts')return guidanceColumns([[guidanceTopic(['A｜本模块说明',guidance[0][1]]),guidanceTopic(['B｜填写重点',guidanceSequence([['01｜选择与识别',guidance[1][1]],['02｜整理建议',guidance[2][1]]])])],[guidanceTopic(['C｜安全边界',guidance[3][1]],'auxiliary'),guidanceTopic(['D｜进一步帮助',guidance[4][1]],'auxiliary')]]);if(moduleId==='conditions')return guidanceColumns([[guidanceTopic(['A｜本模块说明',guidance[0][1]]),guidanceTopic(['B｜需要确认什么',guidanceSequence([['01｜逐项确认',guidance[1][1]],['02｜确认方法',guidance[2][1]]])])],[guidanceTopic(['C｜安全边界',guidance[3][1]],'auxiliary'),guidanceTopic(['D｜文件与补充',`${guidance[4][1]} ${guidance[5][1]}`],'auxiliary')]]);if(moduleId==='assistants'){const intro=[guidance[0][1],guidance[1][1]].join(' ');return guidanceColumns([[guidanceTopic(['A｜本模块说明',intro]),guidanceTopic(['B｜需要记录哪些信息',guidanceSequenceWide(guidance.slice(2,9))])],[guidanceTopic(['C｜必要提醒',guidance[9][1]],'auxiliary'),guidanceTopic(['D｜附件补充',guidance[10][1]],'auxiliary')]]);}if(moduleId==='message'){const expression=`${guidance[1][1]} ${guidance[2][1]}`;return guidanceColumns([[guidanceTopic(['A｜本模块说明',guidance[0][1]]),guidanceTopic(['B｜表达方式',expression])],[guidanceTopic(['C｜可以写些什么',guidanceSequenceWide(guidance.slice(3,8))]),guidanceTopic(['D｜安全边界',guidance[8][1]],'auxiliary'),guidanceTopic(['E｜附件补充','如文字不足，可以使用文字文件、图片、照片、文档、语音留言或视频补充。'],'auxiliary')]]);}return dualBaselineInstructionPanel(moduleId);}
instructionPanel=standardizedInstructionPanel;
const standardizedBaselineInstructionPanel=instructionPanel;
const reorderableGuidanceColumns=columns=>`<details class="module-instructions module-instructions-independent module-instructions-reorderable"><summary>填写说明</summary><div>${columns.map((items,index)=>`<div class="module-guidance-column" data-guidance-column="${index?'right':'left'}">${items.join('')}</div>`).join('')}</div></details>`;
function balancedInstructionPanel(moduleId){const guidance=moduleGuidance[moduleId];if(moduleId==='accounts')return reorderableGuidanceColumns([[guidanceTopic(['A｜本模块说明',guidance[0][1]],'help-a'),guidanceTopic(['C｜安全边界',guidance[3][1]],'auxiliary help-c')],[guidanceTopic(['B｜填写重点',guidanceSequence([['01｜选择与识别',guidance[1][1]],['02｜整理建议',guidance[2][1]]])],'help-b'),guidanceTopic(['D｜进一步帮助',guidance[4][1]],'auxiliary help-d')]]);if(moduleId==='conditions')return reorderableGuidanceColumns([[guidanceTopic(['A｜本模块说明',guidance[0][1]],'help-a'),guidanceTopic(['C｜安全边界',guidance[3][1]],'auxiliary help-c')],[guidanceTopic(['B｜需要确认什么',guidanceSequence([['01｜逐项确认',guidance[1][1]],['02｜确认方法',guidance[2][1]]])],'help-b'),guidanceTopic(['D｜文件与补充',`${guidance[4][1]} ${guidance[5][1]}`],'auxiliary help-d')]]);if(moduleId==='assistants'){const intro=[guidance[0][1],guidance[1][1]].join(' ');return reorderableGuidanceColumns([[guidanceTopic(['B｜需要记录哪些信息',guidanceSequenceWide(guidance.slice(2,9))],'help-b')],[guidanceTopic(['A｜本模块说明',intro],'help-a'),guidanceTopic(['C｜必要提醒',guidance[9][1]],'auxiliary help-c'),guidanceTopic(['D｜附件补充',guidance[10][1]],'auxiliary help-d')]]);}if(moduleId==='message'){const expression=`${guidance[1][1]} ${guidance[2][1]}`;return reorderableGuidanceColumns([[guidanceTopic(['A｜本模块说明',guidance[0][1]],'help-a'),guidanceTopic(['B｜表达方式',expression],'help-b'),guidanceTopic(['D｜安全边界',guidance[8][1]],'auxiliary help-d'),guidanceTopic(['E｜附件补充','如文字不足，可以使用文字文件、图片、照片、文档、语音留言或视频补充。'],'auxiliary help-e')],[guidanceTopic(['C｜可以写些什么',guidanceSequenceWide(guidance.slice(3,8))],'help-c')]]);}return standardizedBaselineInstructionPanel(moduleId);}
instructionPanel=balancedInstructionPanel;
const guidanceChildColumns=(leftItems,rightItems)=>`<div class="module-guidance-child-columns"><div>${leftItems.map(guidanceTopic).join('')}</div><div>${rightItems.map(guidanceTopic).join('')}</div></div>`;
const structuredGuidancePanel=body=>`<details class="module-instructions module-instructions-structured"><summary>填写说明</summary><div>${body}</div></details>`;
function finalizedHelpLayout(moduleId){
  const guidance=moduleGuidance[moduleId];
  if(moduleId==='accounts')return guidanceColumns([
    [guidanceTopic(['A｜本模块说明',guidance[0][1]]),guidanceTopic(['B｜安全边界',guidance[3][1]],'auxiliary'),guidanceTopic(['C｜进一步帮助',guidance[4][1]],'auxiliary')],
    [guidanceTopic(['D｜填写重点',guidanceSequence([['01｜选择与识别',guidance[1][1]],['02｜整理建议',guidance[2][1]]])])]
  ]);
  if(moduleId==='conditions')return guidanceColumns([
    [guidanceTopic(['A｜本模块说明',guidance[0][1]]),guidanceTopic(['B｜安全边界',guidance[3][1]],'auxiliary'),guidanceTopic(['C｜文件与补充',`${guidance[4][1]} ${guidance[5][1]}`],'auxiliary')],
    [guidanceTopic(['D｜需要确认什么',guidanceSequence([['01｜逐项确认',guidance[1][1]],['02｜确认方法',guidance[2][1]]])])]
  ]);
  if(moduleId==='assistants'){
    const intro=`<p>${guidance[0][1]}</p><p><strong>可以记录：</strong>${guidance[1][1]}</p>`;
    return structuredGuidancePanel(`<div class="module-guidance-top">${guidanceTopic(['A｜本模块说明',intro])}${guidanceTopic(['B｜必要提醒',guidance[9][1]],'auxiliary')}</div><section class="module-guidance-group"><h3>C｜需要记录哪些信息</h3>${guidanceChildColumns(guidance.slice(2,6),guidance.slice(6,9))}</section>${guidanceTopic(['D｜附件补充',guidance[10][1]],'auxiliary module-guidance-full')}`);
  }
  if(moduleId==='message'){
    const expression=`${guidance[1][1]} ${guidance[2][1].split('除了帮助未来恢复人')[0].trim()}`;
    return structuredGuidancePanel(`<div class="module-guidance-top">${guidanceTopic(['A｜本模块说明',guidance[0][1]])}${guidanceTopic(['B｜表达方式',expression])}</div><section class="module-guidance-group"><h3>C｜可以写些什么</h3>${guidanceChildColumns(guidance.slice(3,6),guidance.slice(6,8))}</section><div class="module-guidance-bottom">${guidanceTopic(['D｜安全边界',guidance[8][1]],'auxiliary')}${guidanceTopic(['E｜附件补充','如文字不足，可以使用文字文件、图片、照片、文档、语音留言或视频补充。'],'auxiliary')}</div>`);
  }
  return balancedInstructionPanel(moduleId);
}
instructionPanel=finalizedHelpLayout;
const formalTemplateAssets={assistants:'./assets/templates/LEGAVIK_Module5_协助人_Canonical_V2.docx',message:'./assets/templates/LEGAVIK_Module6_给未来恢复人的嘱托_Canonical_V3.1.docx'};
function staticTemplateTool(moduleId){const url=formalTemplateAssets[moduleId];return url?`<button type="button" class="module-template-menu-trigger" data-static-template="${moduleId}" data-template-url="${url}">下载填写模板 <span aria-hidden="true">▾</span></button>`:'';}
function moduleTemplateTools(moduleId){if(moduleId==='conditions')return`<div class="module-template-tools"><button type="button" class="module-guidance-link" data-module-example="conditions">查看填写示例及详细说明 ›</button></div>`;if(!['locations','instructions'].includes(moduleId)){const download=staticTemplateTool(moduleId),helpLabel=['assistants','message'].includes(moduleId)?'查看填写说明 ›':'查看填写示例及详细说明 ›';return download?`<div class="module-template-tools">${download}<button type="button" class="module-guidance-link" data-module-example="${moduleId}">${helpLabel}</button></div>`:'';}const summaryCopy=moduleId==='locations'?'根据当前已选择的账户、钱包和恢复条件生成，适合统一整理多个平台。':'根据当前账户 / 钱包信息生成，适合统一整理多个平台的恢复步骤。',singleCopy=moduleId==='locations'?'为某一个平台或钱包生成独立填写文件，适合复杂账户补充，可重复下载。':'针对某一个平台或钱包单独生成，适合复杂恢复流程，可重复下载。';return`<div class="module-template-tools"><details class="module-template-menu"><summary>下载填写模板 ▾</summary><div class="module-template-panel"><section class="module-template-section"><strong>汇总填写模板</strong><small>${summaryCopy}</small><button type="button" class="module-template-download" data-template-module="${moduleId}" data-template-mode="summary">下载汇总模板</button></section><section class="module-template-section"><strong>单一平台填写模板</strong><select aria-label="选择当前平台或钱包" data-template-account="${moduleId}"><option value="">选择当前平台 / 钱包</option>${Object.values(store.accounts).map(account=>`<option value="${escape(account.account_id)}">${escape(accountLabel(account,templates))}</option>`).join('')}</select><button type="button" class="module-template-download" data-template-module="${moduleId}" data-template-mode="single">下载单一平台模板</button><small>${singleCopy}</small></section></div></details><button type="button" class="module-guidance-link" data-module-example="${moduleId}">查看填写示例及详细说明 ›</button></div>`;}
function moduleAttachmentZone(moduleId){const copy=moduleAttachmentCopy[moduleId],files=Object.values(store.attachments).filter(file=>file.module_id===moduleId),isTemplateModule=['locations','instructions'].includes(moduleId),isSupplementModule=['assistants','message'].includes(moduleId),specialCopy={accounts:'如线上填写仍不足以完整说明本模块信息，可以上传文字、图片、音频或其他支持附件进行补充。',conditions:'如线上选择仍无法充分表达特殊恢复条件，可以上传文字、图片、音频或其他附件进行补充。',locations:'可上传填写模板、文档、图片、语音、视频等资料。如果附件已经完整记录相关信息，在线填写部分无需重复填写。',instructions:'可上传填写模板、文档、图片、语音、视频等资料。如果附件已经完整记录相关信息，在线填写部分无需重复填写。',assistants:'可上传协助说明、截图、文档、语音或其他辅助资料。附件用于补充协助信息，不能替代是否需要协助人的明确选择。',message:'可上传文字、图片、语音、视频或其他补充说明，用于补充想留给未来恢复人的内容。'}[moduleId],auxiliary=moduleId==='accounts'?`<div class="module-template-tools"><button type="button" class="module-guidance-link" data-module-example="${moduleId}">查看填写示例及详细说明 ›</button></div>`:moduleTemplateTools(moduleId),rule=(isTemplateModule||isSupplementModule)?'':copy.rule,example=isTemplateModule?(moduleId==='locations'?'例如：设备位置照片、路径截图或查找指引。':'例如：步骤文档、操作截图、录屏或语音说明。'):copy.example,extra=(isTemplateModule||isSupplementModule)?'<details class="attachment-guidance-more"><summary>展开更多 ▾</summary><div><p>当前 Recovery Map 附件总空间为 50 MB。</p><p>如果预留表格空间不足，可以在 Word 中继续添加行或列，按实际需要扩展填写区域。</p><p>为了让未来恢复人更容易理解和查找，建议附件保持必要、清晰并具有明确用途，避免上传大量重复或无关资料。</p></div></details>':'';return`<section class="module-attachment-zone" data-module-attachment="${moduleId}"><div><h2>补充附件</h2><p>${specialCopy??'可上传与本模块相关的说明、截图、文档、音频或操作指引，用于补充恢复信息。请勿上传私钥、助记词、OTP、Authenticator Seed 或完整密码。'}</p><p class="attachment-example">${example}</p>${rule?`<p class="attachment-rule">${rule}</p>`:''}${extra}${auxiliary}${files.length?`<div class="module-attachment-feedback"><strong>📎 已添加 ${files.length} 个附件</strong>${files.map(file=>`<span>${escape(file.file_name)}</span>`).join('')}</div>`:''}</div></section>`;}
const baseModuleTemplateTools=moduleTemplateTools;
moduleTemplateTools=moduleId=>baseModuleTemplateTools(moduleId).replace('查看填写说明 ›','查看填写示例及详细说明 ›');
const templateExample=(title,body)=>`<details class="module-template-example"><summary>${title}</summary><div>${body}</div></details>`;
const moduleAttachmentTemplateHelp={
  locations:`<section><h3>附件模板填写说明</h3><p>本模板用于把已经确认的恢复条件，进一步落实到具体的访问入口、相关设备和保存位置，让未来恢复人真正能够找到并取得对应材料。</p><p>平台 / 钱包名称、账户类型以及 Module 2 已确认的恢复条件，会根据前面的选择自动带入。</p><p>你主要需要继续补充：</p><ul><li>相关设备；</li><li>访问入口；</li><li>具体保存位置；</li><li>必要的查找说明。</li></ul><h3>关于“无”</h3><p>如果某项条件已经确认不存在或不适用，请明确填写“无”，不要留空。“无”表示已经确认；空白可能让未来恢复人无法判断是“不存在”还是“遗漏未填”。</p><h3>保存位置怎么写</h3><p>保存位置应具体到未来恢复人能够真正定位并取得对应材料。</p><p><strong>物理位置示例：</strong>书房保险柜；书桌左侧第二个抽屉；银行保险箱 A-12。</p><p><strong>电子位置示例：</strong>1Password → Binance Login；备用 iPhone → Authenticator；MacBook → 指定文件夹 / 文件名称。</p><p><strong>避免只写：</strong>家里；电脑里；密码管理器；纸质资料；云端。</p><h3>安全提醒</h3><p>不要在模板中直接填写完整 Seed Phrase / 助记词或完整 Private Key / 私钥。</p><h3>完成后</h3><p>填写完成后保存 DOCX，然后通过 Module 3 现有“添加附件”上传。</p><p>如相关信息已在模板中完整记录，在线填写部分可以省略；如有特别重要的位置或风险提示，也可以继续在线填写作为补充。</p></section><section class="module-template-examples"><h3>附件模板填写示例</h3>${templateExample('中心化交易所填写示例','<h4>Binance｜注册邮箱</h4><p><strong>当前情况：</strong>备用手机仍可访问 Gmail</p><p><strong>具体位置：</strong>备用手机位于书房保险柜</p><p><strong>邮箱密码记录位置：</strong>1Password → Gmail Recovery</p><h4>2FA</h4><p><strong>当前方式：</strong>Authenticator</p><p><strong>所在设备：</strong>备用 iPhone</p><p><strong>设备位置：</strong>书房保险柜</p><p><strong>解锁密码位置：</strong>1Password → Backup iPhone</p><h4>KYC</h4><p><strong>护照原件：</strong>家庭文件柜第二层</p><p><strong>扫描件：</strong>加密 U 盘 → Binance KYC</p>')}${templateExample('DEX / DeFi 填写示例','<h4>Uniswap｜关联钱包</h4><p><strong>当前情况：</strong>通过 MetaMask Main 连接</p><p><strong>访问入口：</strong>备用 MacBook → 官方网页</p><p><strong>相关设备：</strong>备用 MacBook</p><p><strong>设备位置：</strong>书房保险柜</p><p><strong>查找说明：</strong>先确认钱包地址，再连接协议。</p>')}${templateExample('自托管钱包填写示例','<h4>Ledger｜恢复材料</h4><p><strong>Hardware Wallet：</strong>书房保险柜</p><p><strong>Seed Phrase 位置：</strong>银行保险箱 A-12</p><p><strong>Passphrase 线索：</strong>1Password → Ledger Recovery Note</p><p><strong>查找说明：</strong>先核对设备和恢复材料对应的钱包地址。</p>')}${templateExample('多签钱包填写示例','<h4>Multisig｜Signer 与 Threshold</h4><p><strong>Signer 设备：</strong>Signer A 硬件钱包位于书房保险柜</p><p><strong>其他 Signer：</strong>由指定协助人分别保管</p><p><strong>Threshold：</strong>记录在 Multisig Setup 说明文件</p><p><strong>查找说明：</strong>先确认达到 Threshold 所需的 Signer 数量及联系路径。</p>')}</section>`,
  instructions:`<section><h3>附件模板填写说明</h3><p>本模板用于记录在已经找到所需恢复条件和材料之后，应该按照什么顺序重新登录账户、恢复钱包或重新取得控制权。</p><p>平台 / 钱包名称、账户类型以及 Module 2 已确认的恢复条件，会根据前面的选择自动带入。你主要需要填写实际恢复步骤。</p><h3>两种恢复场景</h3><p><strong>A｜现有 / 备用设备可用：</strong>例如备用手机仍可进入 Email、2FA、交易所 App 或钱包。</p><p><strong>B｜原有设备不可用 / 新设备恢复：</strong>例如手机丢失、电脑损坏，需要重新安装 App、重新验证账户或重新恢复钱包。</p><p>两种情况下的恢复路径可能明显不同，因此建议分别记录。</p><h3>步骤怎么写</h3><p>一个步骤只写一个动作。每一步尽量写清要做什么、使用什么，以及完成以后应该看到什么结果。</p><h3>如果关键恢复条件本身失效</h3><p>不要只记录正常情况下的恢复路径。特别是中心化交易所，可以考虑注册邮箱、登录密码、2FA、手机号、KYC 或可信设备无法使用时的备用路径。具体备用路径应以平台 / 钱包真实账户设置和官方恢复流程为准。</p><h3>避免单一手机成为唯一恢复条件</h3><p>如果手机同时承担 Email、短信验证、2FA、可信设备等多个恢复功能，建议确认仍有其他可执行的恢复方式。</p><h3>备用恢复设备与人脸识别</h3><p>备用恢复设备不建议把账户本人的<span class="module-example-emphasis">人脸识别</span>或其他本人专属生物识别，作为进入关键恢复工具的唯一方式。</p><p>如果备用设备用于未来恢复，应确保未来恢复人仍可以通过设备密码、App 密码、Passkey 或其他安全方式进入邮箱、2FA、钱包等关键工具。</p><p>日常使用设备仍可继续使用人脸识别等安全保护；这里强调的是，专门用于未来恢复的备用设备，应避免本人专属生物识别成为恢复障碍。</p><h3>安全提醒</h3><p>记录操作方式和恢复顺序即可。不要在模板中直接填写完整 Seed Phrase 或完整 Private Key。</p><h3>完成后</h3><p>填写完成后保存 DOCX，然后通过 Module 4 现有“添加附件”上传。</p><p>如恢复步骤已在模板中完整记录，在线填写部分可以省略；如有特别重要的步骤、风险点或备用方案，也可以继续在线填写作为补充。</p></section><section class="module-template-examples"><h3>附件模板填写示例</h3>${templateExample('中心化交易所填写示例','<h4>Binance｜A｜现有 / 备用设备可用</h4><ol><li><strong>Step 1：</strong>找到原有 / 备用已信任设备。<br>结果：设备可正常解锁。</li><li><strong>Step 2：</strong>打开交易所官方 App / 官网。<br>结果：确认使用官方入口。</li><li><strong>Step 3：</strong>输入交易所登录信息。<br>结果：账户信息匹配。</li><li><strong>Step 4：</strong>完成注册邮箱验证。<br>结果：邮箱访问正常。</li><li><strong>Step 5：</strong>完成 2FA。<br>结果：验证成功。</li><li><strong>Step 6：</strong>如平台要求，完成其他安全验证。<br>结果：进入账户。</li><li><strong>Step 7：</strong>核对账户身份、资产和安全设置。<br>结果：确认账户正常。</li></ol><h4>B｜原有设备不可用 / 新设备恢复</h4><ol><li>在新设备打开官方入口。</li><li>使用已确认的登录与邮箱恢复条件。</li><li>按平台流程完成 2FA 重置或身份验证。</li><li>进入账户后核对身份、资产和安全设置。</li></ol>')}${templateExample('DEX / DeFi 填写示例','<h4>Uniswap｜恢复路径</h4><ol><li>先恢复并核对关联钱包。</li><li>从官方入口连接协议。</li><li>核对钱包地址、网络和已授权连接。</li><li>确认链上资产和头寸正常显示。</li></ol>')}${templateExample('自托管钱包填写示例','<h4>Ledger / MetaMask｜新设备恢复</h4><ol><li>在新设备安装官方钱包应用。</li><li>使用对应 Seed Phrase 恢复钱包；如实际启用 Passphrase，再恢复对应账户。</li><li>设置新的设备或 App 访问密码。</li><li>核对钱包地址后再确认资产信息。</li></ol>')}${templateExample('多签钱包填写示例','<h4>Multisig｜Threshold 恢复</h4><ol><li>确认需要恢复的多签地址和 Threshold。</li><li>恢复达到 Threshold 数量的 Signer。</li><li>使用官方或已确认入口创建提案。</li><li>由足够 Signer 核对并签名。</li><li>达到 Threshold 后执行并核对结果。</li></ol>')}</section>`
};
const moduleExampleContent={
  accounts:{title:'Module 1｜资产与账户填写示例',body:'<section><h3>填写提醒</h3><p>中心化交易所除了选择平台名称外，还需要额外选择：</p><ul><li>账户所在区域；</li><li>账户类型（个人账户 / 机构账户）。</li></ul><p>这两项属于中心化交易所的必要填写内容。</p><p>其他类型的平台或钱包，按实际使用情况直接选择即可。</p><p>同一平台存在多个独立账户时，可分别添加。</p></section><section><h3>填写示例</h3><dl><div><dt>中心化交易所</dt><dd>Binance｜澳洲｜个人账户</dd></div><div><dt>热钱包 / 软件钱包</dt><dd>MetaMask</dd></div><div><dt>冷钱包 / 硬件钱包</dt><dd>Ledger</dd></div><div><dt>DEX / DeFi</dt><dd>Uniswap</dd></div></dl></section><section><h3>说明</h3><p>示例仅用于帮助理解选择和填写方式，请按照自己的实际账户情况进行选择和填写。</p></section>'},
  conditions:{title:'Module 2｜恢复所需条件填写示例',body:'<section><h3>填写提醒</h3><p>不同账户类型所需的恢复条件可能不同，请以当前账户的真实设置为准逐项确认。</p><p>关键恢复条件应尽量避免遗漏。</p><p>如果不确定某项条件是否真正需要，建议通过：</p><ul><li>实际登录检查；</li><li>轻量恢复演练；</li><li>平台或钱包官方资料；</li></ul><p>进一步确认。</p><ul><li><strong>中心化交易所：</strong>重点确认账户登录、2FA、身份验证以及现有 / 备用设备等恢复条件；</li><li><strong>DEX / DeFi：</strong>重点确认实际使用的钱包方式，以及对应的钱包或账户恢复条件；</li><li><strong>自托管钱包：</strong>重点确认真正用于重新取得钱包控制权的恢复材料；</li><li><strong>多签：</strong>如果使用多签，还需确认 Signer 和 Threshold 等联合签名条件。</li></ul><h3>什么是“现有 / 备用设备”？</h3><p>现有 / 备用设备，是指当前正在使用，或为未来恢复预先准备的手机、电脑或其他设备。</p><p>这些设备可能已经安装并配置交易所、钱包、邮箱、2FA 等关键工具，也可能保留已登录、已配置或可信设备状态。</p><p>如果这些设备未来仍能正常开机、解锁并访问相关工具，通常可以明显降低恢复难度。</p><p>建议定期确认备用设备仍可正常使用，并确保相关 App、邮箱和 2FA 等关键工具仍然有效。</p><h3>恢复设备建议</h3><p>日常使用设备可以继续使用人脸识别等安全保护；如果某台设备专门作为未来恢复的备用设备，建议确认邮箱、2FA、钱包等关键 App 不会因为只能识别账户本人而导致恢复人无法进入。</p><p>必要时可改用设备密码、App 密码、Passkey 或其他可执行的安全访问方式，在日常安全与未来可恢复性之间保持平衡。</p></section><section><h3>填写示例</h3><div class="module-example-cases"><article><strong>示例 1｜Binance</strong><ul><li>注册邮箱</li><li>交易所登录密码</li><li>2FA</li><li>KYC / 身份资料</li><li>现有 / 备用设备（如备用手机、备用电脑）</li></ul></article><article><strong>示例 2｜Ledger</strong><ul><li>Hardware Wallet / 硬件钱包</li><li>Seed Phrase / 助记词</li><li>Passphrase / 额外口令</li><li>现有 / 备用设备（如备用手机、备用电脑）</li></ul></article><article><strong>示例 3｜MetaMask</strong><ul><li>Seed Phrase / 助记词</li><li>钱包访问密码</li><li>现有 / 备用设备（如备用手机、备用电脑）</li></ul></article></div></section><section><h3>说明</h3><p>示例仅用于帮助理解恢复条件的选择方式。不同平台和钱包的真实恢复条件可能不同，请根据自己的实际账户设置进行确认和选择。</p></section>'},
  locations:{title:'Module 3｜位置与查找填写示例及详细说明',body:'<section><h3>什么是“现有 / 备用设备”</h3><p>现有 / 备用设备，是指当前正在使用，或为未来恢复预先准备的手机、电脑或其他设备。这些设备可能已经安装并配置交易所、钱包、邮箱、2FA 等关键工具，也可能保留已登录、已配置或可信设备状态。</p><p>在本模块中，请记录这些设备本身在哪里，以及未来恢复人如何安全找到并访问它们。</p></section><section><h3>保存位置怎样才算“可找到”</h3><p>保存位置应具体到未来恢复人能够真正定位并取得对应材料。</p><div class="module-example-subgroup"><strong>具体描述示例</strong><p>物理位置：</p><ul><li>书房保险柜</li><li>卧室衣柜上层密码盒</li><li>银行保险箱 A-12</li></ul><p>电子位置：</p><ul><li>MacBook 上的 1Password → Binance Login</li><li>备用 iPhone 中的 Authenticator</li></ul></div><div class="module-example-subgroup"><strong>过于抽象的描述示例</strong><ul><li>家里</li><li>电脑里</li><li>密码管理器</li><li>纸质资料</li><li>云端</li></ul></div><p>这类过于抽象的描述通常不足以让未来恢复人准确定位材料，因此应尽量记录更具体的位置或访问路径。</p></section><section><h3>填写示例</h3><div class="module-example-cases"><article><strong>示例 1｜Binance</strong><ul><li>注册邮箱：Gmail</li><li>2FA：备用 iPhone</li><li>KYC 资料：书房文件柜第二层</li><li>现有 / 备用设备：备用 iPhone，书房保险柜</li></ul></article><article><strong>示例 2｜MetaMask</strong><ul><li>Seed Phrase：书房保险柜</li><li>钱包访问密码：密码管理器 → MetaMask Main</li><li>现有 / 备用设备：备用 MacBook</li></ul></article><article><strong>示例 3｜Ledger</strong><ul><li>Hardware Wallet：书房保险柜</li><li>Seed Phrase：银行保险箱</li><li>Passphrase：密码管理器中的指定条目</li></ul></article></div></section><section><h3>恢复设备建议</h3><p>日常使用设备可以继续使用人脸识别等安全保护；如果某台设备专门作为未来恢复的备用设备，建议确认邮箱、2FA、钱包等关键 App 不会因为只能识别账户本人而导致恢复人无法进入。</p><p>必要时可使用设备密码、App 密码、Passkey 或其他可执行的安全访问方式，在日常安全与未来可恢复性之间保持平衡。</p></section>'},
  instructions:{title:'Module 4｜恢复与转移步骤填写示例及详细说明',body:'<section><h3>两种恢复场景</h3><article><strong>现有 / 备用设备可用</strong><p>指当前设备或预先准备的备用手机、电脑仍可正常使用，并能够进入相关邮箱、2FA、交易所 App、钱包或其他关键恢复工具。</p><p>在这种情况下，可以优先利用已有登录状态、可信设备或已经配置好的恢复工具，恢复路径通常更短。</p></article><article><strong>原有设备不可用 / 新设备恢复</strong><p>如果原有手机、电脑丢失、损坏或无法访问，则需要在新设备上重新建立恢复环境。</p><p>此时可能需要使用：</p><ul><li>Email</li><li>登录密码</li><li>2FA Recovery Code</li><li>KYC</li><li>Seed Phrase</li><li>Private Key</li><li>Passphrase</li><li>Hardware Wallet</li></ul><p>具体以真实账户设置为准。</p></article></section><section><h3>如果关键恢复条件本身无法使用</h3><p>记录恢复步骤时，不仅要写正常路径，也建议考虑关键恢复条件本身失效时的备用路径。</p><p>特别是中心化交易所，可以确认：</p><ul><li>注册邮箱无法登录时，邮箱自身如何恢复；</li><li>忘记交易所登录密码时，平台密码找回路径；</li><li>2FA 设备丢失或 Authenticator 无法使用时，是否有 2FA 恢复码或平台重置流程；</li><li>注册手机号不可用时，是否有其他验证方式；</li><li>KYC 被触发时，需要准备哪些身份资料；</li><li>可信设备失效时，如何在新设备重新建立可信状态。</li></ul><p>具体恢复方式请以对应平台或钱包的真实账户设置和官方恢复流程为准。</p></section><section><h3>避免单一设备成为唯一恢复条件</h3><p>如果手机同时承担邮箱、短信验证、2FA 或可信设备等多个恢复功能，建议确认仍有其他可执行的恢复方式，避免单一手机成为唯一不可替代的恢复条件。</p></section><section><h3>备用恢复设备建议</h3><p>备用恢复设备不建议把账户本人的<span class="module-example-emphasis">人脸识别</span>或其他本人专属生物识别，作为进入关键恢复工具的唯一方式。</p><p>如果备用设备用于未来恢复，应确保未来恢复人仍可以通过设备密码、App 密码、Passkey 或其他安全方式进入邮箱、2FA、钱包等关键工具。</p><p>日常使用设备仍可继续使用<span class="module-example-emphasis">人脸识别</span>等安全保护；这里强调的是，专门用于未来恢复的备用设备，应避免本人专属生物识别成为恢复障碍。</p></section><section><h3>如何写步骤</h3><ul><li>一个步骤只写一个动作；</li><li>按顺序；</li><li>写清结果；</li><li>不要把多个操作塞在同一步。</li></ul></section><section><h3>填写示例</h3><div class="module-example-cases"><article><strong>示例 1｜Binance</strong><ol><li>打开官方 Binance App 或官网；</li><li>使用注册邮箱和登录密码进入账户；</li><li>完成 2FA；</li><li>如触发身份验证，按照账户要求完成；</li><li>确认账户和资产可以正常访问。</li></ol></article><article><strong>示例 2｜MetaMask</strong><ol><li>在新设备安装官方 MetaMask；</li><li>选择恢复现有钱包；</li><li>使用 Seed Phrase 恢复；</li><li>设置新的钱包访问密码；</li><li>确认钱包地址和资产信息正确。</li></ol></article><article><strong>示例 3｜Ledger</strong><ol><li>准备 Ledger 设备；</li><li>如需恢复新设备，进入 Restore 流程；</li><li>使用 Seed Phrase 完成恢复；</li><li>如果使用 Passphrase，再恢复对应账户；</li><li>连接兼容钱包软件，确认地址正确。</li></ol></article></div></section><section><h3>恢复演练提醒</h3><p>在正式保存恢复步骤之前，建议尽可能进行一次实际登录检查或轻量恢复演练。</p><p>这样可以确认记录的步骤是否真实可执行，同时帮助发现 Module 2 是否遗漏恢复条件、Module 3 是否遗漏关键位置。</p></section>'}
};
moduleExampleContent.assistants={title:'Module 5｜协助人填写说明',body:`<section><h3>填写说明</h3><p>本模块用于记录未来恢复过程中可能提供帮助的人或机构，以及什么时候联系他们、他们可以协助什么。</p><p>可以记录的协助人包括家庭成员、信任的人、律师、遗嘱执行人、受托人、会计师、税务或财富顾问、技术协助人、多签 Signer、公司或其他专业机构。</p><h4>01｜协助人是谁</h4><p>记录姓名或机构，以及其角色或与账户持有人的关系。</p><h4>02｜什么时候联系</h4><p>说明未来恢复人在什么情况下需要联系此人或机构。</p><h4>03｜可以协助什么</h4><p>说明可以提供的具体帮助，不要只写“可以帮忙”。</p><h4>04｜身份与权限</h4><p>如具有律师、Executor、Trustee、Signer、公司管理员等正式身份，可进行说明。</p><h4>05｜已知或可协助查找的信息</h4><p>说明其知道哪些信息、可以帮助找到哪些材料、设备或文件。</p><h4>06｜替代联系人</h4><p>如主要协助人无法联系，可以记录备用联系人或机构。</p><h4>07｜及时更新</h4><p>联系方式、角色、权限或可用性发生变化时，应及时更新。</p><h4>必要提醒</h4><ul><li>被列为协助人，不代表拥有资产控制权；</li><li>不建议任何一个协助人集中掌握全部控制材料；</li><li>完整 Seed Phrase / 助记词和完整 Private Key / 私钥不应交给任何协助人。</li></ul><p>如果文字不足，可使用文字文件、图片、文档、语音留言等附件补充。</p><p>如果不需要协助人，可以明确选择“不需要”。</p></section>`};
moduleExampleContent.message={title:'Module 6｜给未来恢复人的嘱托填写说明',body:`<section><h3>填写说明</h3><p>本模块用于留下前面几个模块无法完整表达的重要提醒、个人安排，以及你真正想对未来恢复人说的话。</p><p>你可以说明需要特别注意的事情和特殊背景，也可以留下你对财富、家庭、责任和人生的理解。</p><p>这里没有标准答案，也不要求全部填写。</p><p>你可以只留下几句话，也可以通过文字、图片、照片、语音留言或视频留下更完整的表达。</p><p><strong>有些财富可以被转移，有些价值只能被传递。</strong></p><p>除了帮助未来恢复人理解这些资产，也可以让他们理解你为什么这样安排，以及你真正希望留下什么。</p><h4>01｜重要提醒与特殊安排</h4><p>记录前面模块难以表达、但未来恢复人确实需要知道的重点。</p><h4>02｜关于这些资产与财富，我想留下的想法</h4><p>可以写这些资产为什么重要、你如何理解财富，以及你希望它们未来发挥什么价值。</p><h4>03｜我最想对你说的话</h4><p>可以是一段话、一封信，或任何真正希望未来恢复人、家人或重要的人看到的内容。</p><h4>04｜留下文字，也可以留下声音和影像</h4><p>如文字不足，可以通过图片、照片、语音留言或视频补充。</p><p><strong>留下的不只是信息，也可以是你的声音。</strong></p><h4>05｜更新与确认</h4><p>当重要安排、账户状态或附件发生变化后，请及时更新相关内容。</p><p>不要在本模块直接写入完整 Seed Phrase / 助记词、Private Key / 私钥、OTP、Authenticator Seed 或完整密码。</p><p>如涉及最终资产归属、遗嘱、信托或其他法律分配事项，以正式生效的法律文件为准。</p></section>`};
moduleExampleContent.locations.templateBody=moduleAttachmentTemplateHelp.locations;
moduleExampleContent.instructions.templateBody=moduleAttachmentTemplateHelp.instructions;
const expandableTemplateNote='<section><h3>附件上传</h3><p>可上传文档、图片、语音、视频等资料。单个文件不超过 10 MB，当前 Recovery Map 附件总空间为 50 MB。</p></section><section><h3>模板扩展</h3><p>如果预留表格空间不足，可以在 Word 中继续添加行或列，按实际需要扩展填写区域。</p></section>';
moduleExampleContent.locations.templateBody+=expandableTemplateNote;
moduleExampleContent.instructions.templateBody+=expandableTemplateNote;
moduleExampleContent.assistants.body=moduleExampleContent.assistants.body.replace('</section>',`${expandableTemplateNote}</section>`);
moduleExampleContent.message.body=moduleExampleContent.message.body.replace('</section>',`${expandableTemplateNote}</section>`);
const directBackupDeviceAdvice='<section><h3>备用恢复设备建议</h3><p>备用恢复设备不建议把账户本人的<span class="module-example-emphasis">人脸识别</span>或其他<span class="module-example-emphasis">本人专属生物识别</span>，作为进入关键恢复工具的<span class="module-example-emphasis">唯一方式</span>。</p><p>如果备用设备用于未来恢复，应确保未来恢复人仍可以通过设备密码、App 密码、Passkey 或其他安全方式进入邮箱、2FA、钱包等关键工具。</p></section>';
moduleExampleContent.locations.body=moduleExampleContent.locations.body.replace(/<section><h3>恢复设备建议<\/h3>[\s\S]*?<\/section>$/,directBackupDeviceAdvice);
moduleExampleContent.instructions.body=moduleExampleContent.instructions.body.replace('<p>日常使用设备仍可继续使用<span class="module-example-emphasis">人脸识别</span>等安全保护；这里强调的是，专门用于未来恢复的备用设备，应避免本人专属生物识别成为恢复障碍。</p>','');
moduleExampleContent.locations.templateBody=moduleExampleContent.locations.templateBody.replace('<h3>关于“无”</h3>','<h3>什么是“现有 / 备用设备”</h3><p>现有 / 备用设备，是指当前正在使用，或为未来恢复预先准备的手机、电脑或其他设备。</p><p>这些设备可能已经安装并配置交易所、钱包、邮箱、2FA 等关键工具，也可能保留已登录、已配置或可信设备状态。</p><p>在模板中，应记录设备是什么、设备在哪里、它承载哪些恢复功能，以及未来恢复人如何安全访问。</p><h3>避免手机成为唯一恢复条件</h3><p>如果手机同时承担注册手机号、邮箱访问、短信验证、2FA 或可信设备等多个恢复功能，建议确认仍有其他可执行的恢复方式，避免单一手机成为唯一且不可替代的恢复条件。</p>'+directBackupDeviceAdvice.replace('<section>','').replace('</section>','')+'<h3>正常登录失败时的备用渠道</h3><p>如果注册邮箱、密码、2FA 等正常恢复条件无法使用，可在模板对应区域记录平台官方客服 / 账户恢复入口或其他官方身份核验渠道。</p><p>该内容只作为常规恢复条件失效时的备用路径。具体方式以对应平台真实账户设置和官方流程为准。</p><h3>关于“无”</h3>').replace('<h3>完成后</h3>','<h3>更新提醒</h3><p>如果设备、文件、账户恢复资料或保存位置发生变化，应及时更新模板，使未来恢复人看到的仍是最新、有效的信息。</p><h3>完成后</h3>').replace('<p><strong>扫描件：</strong>加密 U 盘 → Binance KYC</p>','<p><strong>扫描件：</strong>加密 U 盘 → Binance KYC</p><p><strong>正常登录失败：</strong>记录平台官方客服 / 账户恢复入口</p>');
moduleExampleContent.instructions.templateBody=moduleExampleContent.instructions.templateBody.replace('<h3>两种恢复场景</h3>','<h3>开始前先确认</h3><p>在记录或执行恢复步骤之前，建议先确认：</p><ul><li>Module 2 所需恢复条件已经准备；</li><li>Module 3 关键材料和设备已经找到；</li><li>当前使用的是对应平台 / 钱包的官方入口；</li><li>当前记录的恢复条件和位置仍然有效。</li></ul><h3>两种恢复场景</h3>').replace('<p>日常使用设备仍可继续使用人脸识别等安全保护；这里强调的是，专门用于未来恢复的备用设备，应避免本人专属生物识别成为恢复障碍。</p>','').replace('<h3>安全提醒</h3>','<h3>建议验证恢复步骤</h3><p>正式保存恢复步骤之前，建议尽可能进行一次实际登录检查或轻量恢复演练。</p><p>这样可以帮助确认记录的步骤真实可执行、Module 2 是否遗漏恢复条件、Module 3 是否遗漏关键位置或设备，以及现有恢复资料是否仍然有效。</p><h3>安全提醒</h3>').replace('<li>按平台流程完成 2FA 重置或身份验证。</li>','<li>按平台官方恢复流程处理 Email、2FA 或身份验证失效。</li>');
function openModuleExample(moduleId,trigger){const content=moduleExampleContent[moduleId];if(!content)return;const overlay=document.querySelector('#overlay-root'),scrollY=window.scrollY,templateBody=canonicalAttachmentTemplateHelp[moduleId]??content.templateBody,hasTabs=Boolean(templateBody);overlay.innerHTML=`<div class="module-example-overlay"><aside class="module-example-drawer" role="dialog" aria-modal="true" aria-labelledby="module-example-title"><button type="button" class="secondary module-example-close" aria-label="关闭填写示例">关闭</button><h2 id="module-example-title">${content.title}</h2>${hasTabs?`<div class="module-example-tabs" role="tablist" aria-label="填写帮助类型"><button type="button" role="tab" aria-selected="true" data-help-tab="online">在线填写说明与示例</button><button type="button" role="tab" aria-selected="false" data-help-tab="template">附件模板填写说明与示例</button></div><div class="module-example-tab-panel" data-help-panel="online">${content.body}</div><div class="module-example-tab-panel" data-help-panel="template" hidden>${templateBody}</div>`:content.body}</aside></div>`;document.body.classList.add('module-example-open');if(hasTabs)overlay.querySelectorAll('[data-help-tab]').forEach(tab=>tab.onclick=()=>{overlay.querySelectorAll('[data-help-tab]').forEach(item=>item.setAttribute('aria-selected',String(item===tab)));overlay.querySelectorAll('[data-help-panel]').forEach(panel=>panel.hidden=panel.dataset.helpPanel!==tab.dataset.helpTab);});const close=()=>{document.removeEventListener('keydown',onKey);document.body.classList.remove('module-example-open');overlay.replaceChildren();window.scrollTo({top:scrollY,behavior:'auto'});trigger.focus({preventScroll:true});},onKey=event=>{if(event.key==='Escape')close();};overlay.querySelector('.module-example-close').onclick=close;overlay.querySelector('.module-example-overlay').onclick=event=>{if(event.target===event.currentTarget)close();};document.addEventListener('keydown',onKey);overlay.querySelector('.module-example-close').focus({preventScroll:true});}
function standardizeDetailedHelp(moduleId){if(!['assistants','message'].includes(moduleId))return;const drawer=document.querySelector('.module-example-drawer'),root=drawer?.querySelector(':scope > section');if(!root||root.classList.contains('module-example-numbered-help'))return;if(moduleId==='message'){const safety=[...root.querySelectorAll(':scope > p')].find(item=>item.textContent.trim().startsWith('不要在本模块直接写入'));if(safety){const heading=document.createElement('h4');heading.textContent='安全边界';safety.before(heading);}}const wrapper=document.createElement('div');wrapper.className='module-example-numbered-help';let topic=null;for(const node of [...root.childNodes]){if(node.nodeType===Node.ELEMENT_NODE&&['H3','H4'].includes(node.tagName)){topic=document.createElement('section');topic.className='module-example-numbered-topic';const heading=document.createElement('h3');heading.textContent=node.textContent.replace(/^\d+｜/,'');topic.append(heading);wrapper.append(topic);node.remove();}else if(topic)topic.append(node);else wrapper.append(node);}root.replaceWith(wrapper);}
function standardizeAllDetailedHelp(moduleId){if(!['accounts','conditions','assistants','message'].includes(moduleId))return;const drawer=document.querySelector('.module-example-drawer'),sources=[...drawer?.querySelectorAll(':scope > section')??[]];if(!sources.length||drawer.querySelector('.module-example-numbered-help'))return;if(moduleId==='message'){const safety=sources.flatMap(source=>[...source.querySelectorAll(':scope > p')]).find(item=>item.textContent.trim().startsWith('不要在本模块直接写入'));if(safety){const heading=document.createElement('h4');heading.textContent='安全边界';safety.before(heading);}}const wrapper=document.createElement('div');wrapper.className='module-example-numbered-help';for(const source of sources){let topic=null;for(const node of [...source.childNodes]){if(node.nodeType===Node.ELEMENT_NODE&&['H3','H4'].includes(node.tagName)){topic=document.createElement('section');topic.className='module-example-numbered-topic';const heading=document.createElement('h3');heading.textContent=node.textContent.replace(/^\d+｜/,'');topic.append(heading);wrapper.append(topic);node.remove();}else if(topic)topic.append(node);else wrapper.append(node);}source.remove();}drawer.append(wrapper);}
app.addEventListener('click',event=>{const trigger=event.target.closest('[data-module-example]');if(trigger){openModuleExample(trigger.dataset.moduleExample,trigger);standardizeAllDetailedHelp(trigger.dataset.moduleExample);}});
app.addEventListener('click',async event=>{const trigger=event.target.closest('[data-template-module]');if(!trigger)return;const moduleId=trigger.dataset.templateModule,mode=trigger.dataset.templateMode,accountId=mode==='single'?app.querySelector(`[data-template-account="${moduleId}"]`)?.value:null;if(mode==='single'&&!accountId)return show('请先选择一个当前平台或钱包。');try{const payload=moduleId==='instructions'?buildFutureModule4TemplatePayload(store,summaryOptions()):buildFutureModule3TemplatePayload(store,summaryOptions()),documentFile=await createDynamicDocxTemplate(payload,{moduleId,accountId}),result=await saveBytesLocally({bytes:documentFile.bytes,suggestedName:documentFile.filename,mimeType:documentFile.mime_type});if(result.status!=='cancelled')show('填写模板已根据当前 Module 1 / 2 数据在浏览器本地生成。');}catch(error){show(error.message==='TEMPLATE_ACCOUNT_REQUIRED'?'请先在 Module 1 添加平台或钱包。':'填写模板未能生成，请检查当前账户和恢复条件。');}});
app.addEventListener('click',async event=>{const trigger=event.target.closest('[data-static-template]');if(!trigger)return;try{const response=await fetch(trigger.dataset.templateUrl,{cache:'no-store'});if(!response.ok)throw new Error('TEMPLATE_FETCH_FAILED');const bytes=new Uint8Array(await response.arrayBuffer()),name=decodeURIComponent(trigger.dataset.templateUrl.split('/').at(-1)),result=await saveBytesLocally({bytes,suggestedName:name,mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});if(result.status!=='cancelled')show('填写模板已保存到你选择的位置。');}catch(error){show(error.name==='AbortError'?'已取消保存。':'填写模板未能保存，请重试。');}});
const systemSummaryMeta={module_1:{module:'资产与账户',purpose:'资产与账户汇总',button:'下载资产与账户汇总文件'},module_2:{module:'恢复所需条件与资料',purpose:'恢复条件汇总',button:'下载恢复条件汇总文件'}};
const systemSummaryCard=key=>{const item=systemSummaryMeta[key];return`<article class="card system-generated-file"><p class="eyebrow">系统生成文件</p><strong>${item.purpose}</strong><p>所属模块：${item.module} · 用途：${item.purpose}</p><button type="button" class="secondary" data-system-summary="${key}">${item.button}</button></article>`;};
app.addEventListener('click',async event=>{const trigger=event.target.closest('[data-system-summary]');if(!trigger)return;trigger.disabled=true;try{const documents=await prepareSystemSummaryDocuments(store,summaryOptions()),file=documents[trigger.dataset.systemSummary];await saveBytesLocally({bytes:file.bytes,suggestedName:file.filename,mimeType:file.mime_type,picker:null});}catch(error){show(error.message==='TEMPLATE_ACCOUNT_REQUIRED'?'请先完成对应模块的必要选择。':`系统生成文件下载失败：${error?.message??'请重试。'}`);}finally{trigger.disabled=false;}});
function readinessPercent(){if(receipt?.generation_allowed)return 100;const statuses=Object.values(receipt?.module_statuses??{}),complete=statuses.filter(item=>['COMPLETE','VERIFIED'].includes(item.state)).length;return Math.round(complete/6*100);}
function injectReadiness(){if(current!=='report')return;const percent=readinessPercent(),target=document.querySelector('main>h1');if(!target)return;const section=document.createElement('section');section.className='readiness-summary';section.innerHTML=`<div><strong>${percent}%</strong><span>准备完成度</span></div><progress value="${percent}" max="100" aria-label="恢复准备完成度 ${percent}%"></progress><p>${percent===100?'六个模块均已准备完成。':'请按各模块的填写说明完成核心选择；位置、步骤等说明类内容可按页面规则使用文字或附件。'}</p>`;target.insertAdjacentElement('afterend',section);if(versionUpdateContext){const summary=document.createElement('section'),states=Object.values(versionUpdateContext.moduleStates),modified=states.filter(value=>value==='已修改').length;summary.className='card version-update-summary';summary.innerHTML=`<p class="eyebrow">更新摘要</p><h2>创建 V${store.version.version_number}</h2><p>变化类型：${versionUpdateContext.changeTypes.map(escape).join('、')||'没有明显变化，只想检查'}</p><p>已修改模块：${modified} · 附件：${Object.keys(store.attachments).length}</p>`;section.insertAdjacentElement('afterend',summary);}}
const formatBytes=value=>formatByteSize(value);
const normalizeCustomerByteText=node=>{if(!node?.textContent||!node.matches?.('#mainnet-details,#internal-details'))return;const next=node.textContent.replace(/([\d,]+) bytes/g,(_,raw)=>`约 ${formatBytes(Number(raw.replaceAll(',','')))}`);if(next!==node.textContent)node.textContent=next;};
new MutationObserver(records=>{for(const record of records)normalizeCustomerByteText(record.target.nodeType===Node.TEXT_NODE?record.target.parentElement:record.target);}).observe(app,{subtree:true,childList:true,characterData:true});
const attachmentAccept=attachmentPolicy.allowed_media.flatMap(item=>item.extensions.map(extension=>`.${extension}`)).join(',');
const uploadPolicyNotice=()=>`<p class="single-upload-hint">每次上传 1 个文件，完成后可继续添加。</p><details class="upload-policy"><summary>查看支持格式与安全要求</summary><p>${attachmentPolicy.allowed_media.map(item=>`<strong>${escape(item.category)}：</strong>${item.extensions.map(extension=>extension.toUpperCase()).join('、')}`).join('　')}</p><p>单文件 ≤ ${Math.round(attachmentPolicy.limits.max_attachment_bytes/1048576)} MiB · 总容量 ≤ ${Math.round(attachmentPolicy.limits.max_version_bytes/1048576)} MiB。视频通常较大，建议仅上传必要短视频。</p><p><strong>禁止上传：</strong>助记词、私钥、完整密码、OTP、验证码。</p></details>`;
function pendingAccountInput(){return{platform_id:document.querySelector('#new-platform')?.value??'',region:document.querySelector('#new-region')?.value??'',account_type:document.querySelector('#new-type')?.value??'',display_label:document.querySelector('#new-label')?.value??''};}
function addPendingAccount(base=store){return commitPendingAccount(base,pendingAccountInput(),{accountId:uid('account'),platformName:platformName(pendingAccountInput().platform_id)});}
function persistDraft(){v3State.updated_at=new Date().toISOString();v3State.current_view=current;v3State.attachment_manifest=Object.values(store.attachments).map(file=>({attachment_id:file.attachment_id,file_name:file.file_name,module_id:file.module_id,account_id:file.account_id,byte_length:file.byte_length}));const status=document.querySelector('#save-state');if(status)status.textContent=Object.keys(store.attachments).length?'✓ 当前创建进度已保存于本次会话 · 附件仅保留在当前安全会话':'✓ 当前创建进度已保存于本次会话';}
function recalc(){receipt=validateProductStore(store,{platformTemplates:templates,rules});generationPreflight=generationPreflightFor(receipt);report=null;artifacts=null;if(versionUpdateSourceDiagnostics)document.documentElement.dataset.module3Diagnostics=JSON.stringify(summarizeVersionUpdateRuntime({source:versionUpdateSourceDiagnostics,store,receipt}));if(versionUpdateContext)rememberVersionOperationContext(store.draft_id);persistDraft();}
const diagnostics=()=>({draft_id:store.draft_id,version_id:store.version.version_id,view_id:current,active_module_id:appState.active_module_id,draft_revision:store.draft_revision,accounts:Object.values(store.accounts).map(account=>({account_id:account.account_id,label:accountLabel(account,templates),condition_count:selectedConditions(store,account.account_id).length,has_instruction:Boolean(store.recovery_instructions[account.account_id]?.instruction_text)})),coverages:Object.values(store.location_coverages).map(item=>({account_id:item.account_id,mode:item.mode,covered_condition_ids:[...item.covered_condition_ids],has_text:Boolean(item.description||item.location_name)})),attachments:Object.values(store.attachments).map(file=>({attachment_id:file.attachment_id,account_id:file.account_id,module_id:file.module_id,purpose:file.purpose})),assistant_decision:store.assistant_decision,has_personal_message:Boolean(store.personal_message?.text)});window.__CJAS_V2_DIAGNOSTICS__=diagnostics;
const summaryOptions=()=>({platformTemplates:templates,conditionLabels,conditionLabelForAccount});
Object.defineProperty(window,'__CJAS_MODULE_EXPORT_PREPARATION__',{value:Object.freeze({systemFiles:()=>prepareSystemSummaryDocuments(store,summaryOptions()),module3:()=>buildFutureModule3TemplatePayload(store,summaryOptions()),module4:()=>buildFutureModule4TemplatePayload(store,summaryOptions())}),enumerable:false,writable:false,configurable:false});
function productErrorMessage(error){const messages={GENERATED_VERSION_IMMUTABLE:'当前版本已生成。需要修改时，请基于此版本创建新草稿。',STALE_DRAFT_REVISION:'资料已更新，请检查当前页面后再次保存；系统没有丢弃任何内容。'};return messages[error?.message]??(versionUpdateContext?'操作未完成，请检查当前页面后重试。':error?.message)??'操作未完成，请检查当前页面后重试。';}
function act(fn){try{store=fn();if(versionUpdateContext&&flow.slice(0,6).includes(current))versionUpdateContext.moduleStates[current]='已修改';recalc();return true;}catch(error){show(productErrorMessage(error));return false;}}
function show(message){if(!broadcastAttempted&&!publishCommitmentPending({signedTransaction:pendingMainnetTransaction,transactionId:currentOperation?.transaction_id,evidence:mainnetEvidence}))setPublishSafetyLock(false);const node=document.querySelector('#message');if(node){node.className='card error';node.textContent=message;}}
let lastAttachmentBusinessError='';
function showBusinessError(error){const code=error?.code??error?.message,messages={ATTACHMENT_SCOPE_INVALID:'请选择该附件所属账户、用途以及需要覆盖的恢复条件。',ATTACHMENT_OWNER_INVALID:'请选择该附件所属的有效账户。',ATTACHMENT_COVERAGE_INVALID:'附件只能覆盖该账户已经选择的恢复条件。',ATTACHMENT_BYTES_INVALID:'附件内容为空或读取不完整，请重新选择文件。',ATTACHMENT_MIME_REQUIRED:'无法识别附件类型，请选择带有正确文件类型的文件。',ATTACHMENT_CAPACITY_EXCEEDED:'附件数量或容量超过当前版本限制。',ATTACHMENT_HASH_INVALID:'附件完整性校验失败，请重新选择文件。',EMPTY_ATTACHMENT:'文件没有有效内容，请重新选择。',UNSUPPORTED_ATTACHMENT_TYPE:'暂不支持此文件格式，请选择支持的文档、图片、音频或视频。',ATTACHMENT_TOO_LARGE:`单个附件不得超过 ${Math.round(attachmentPolicy.limits.max_attachment_bytes/1048576)} MiB。`,TOO_MANY_ATTACHMENTS:'当前 Recovery Map 已包含较多附件。为了保持整理和恢复体验，请先整理现有附件或联系支持。',VAULT_TOO_LARGE:'当前 Recovery Map 的附件总量将超过 50 MiB，请先整理现有附件或选择较小的文件。'};lastAttachmentBusinessError=messages[code]??'附件未能保存，请检查文件和归属后重试。';show(lastAttachmentBusinessError);}
function renderVersionUpdateLoading(){app.innerHTML='<section class="card"><p class="eyebrow">LEGAVIK VERSION UPDATE</p><h1>正在安全加载当前版本</h1><p>当前版本只会在浏览器内解密并建立新 Draft，不会把明文上传服务器。</p><p id="message" role="status">等待已验证的恢复页面传递当前版本…</p></section>';}
function renderVersionUpdateFailure(message='Recovery Map 未能正常打开，请重新加载或返回客户中心。'){current='version-update-loading';app.dataset.runtimeState='FAILED';app.innerHTML=`<section class="card initialization-failure" role="alert"><h1>Recovery Map 未能正常打开</h1><p>${escape(message)}</p><div class="actions"><button id="reload-version-update">重新加载</button><a class="button secondary" href="${canonicalAccountUrl('center',{section:'maps'})}">返回客户中心</a></div></section>`;document.querySelector('#reload-version-update').onclick=()=>location.reload();}
function decorateVersionDownloads(){if(!versionUpdateContext||current!=='downloads'||!artifacts||!mainnetEvidence)return;const version=`V${store.version.version_number}`,snapshotId=artifacts.snapshot.snapshot_id,evidenceBytes=new TextEncoder().encode(JSON.stringify(mainnetEvidence,null,2));app.querySelector('.eyebrow')?.replaceChildren(document.createTextNode('LEGAVIK · DIGITAL ASSET RECOVERY & LEGACY'));app.querySelector('h1')?.insertAdjacentHTML('afterend',`<p class="security-note">这是 ${version} 的恢复材料。请与旧版本恢复材料分开识别和保存。</p>`);for(const[kind,data,name,mime]of[['kit',artifacts.kitBytes,`Recovery-Kit-LEGAVIK-${version}-${snapshotId}.cjas`,'application/octet-stream'],['evidence',evidenceBytes,`Mainnet-Recovery-Evidence-LEGAVIK-${version}-${snapshotId}.json`,'application/json'],['archive',artifacts.archiveBytes,`Local-Encrypted-Backup-LEGAVIK-${version}-${snapshotId}.cjasvault`,'application/octet-stream']])document.querySelector(`#${kind}`).onclick=async()=>{const result=await saveBytesLocally({bytes:data,suggestedName:name,mimeType:mime}),saved=result.status==='saved'||result.status==='download-started';document.querySelector(`#${kind}-status`).textContent=result.status==='cancelled'?'已取消，未标记完成。':saved?'已保存或下载已开始。':'尚未保存';};const actions=app.querySelector('.actions');if(actions)actions.innerHTML=`<a class="button" href="${canonicalAccountUrl('center',{section:'maps'})}">返回客户中心查看版本</a>`;}
function nav(moduleId,anchor){if(moduleId==='attachments')return openAttachmentCenter();navTo(moduleId,anchor);}
function render(anchor=null,{resetScroll=false}={}){const scrollY=window.scrollY;({'version-update-loading':renderVersionUpdateLoading,guide:renderRecoveryGuide,'module-detail':renderModuleDetail,'purchase-plans':renderPurchasePlans,'purchase-register':renderPurchaseRegister,'purchase-otp':renderPurchaseRegister,'purchase-checkout':renderPurchasePlaceholder,'purchase-success':renderPurchasePlaceholder,'purchase-placeholder':renderPurchasePlaceholder,dashboard:versionUpdateContext?renderVersionUpdateDashboard:renderDashboardV5,before:renderBeforeBegin,accounts:renderAccountsV4,conditions:renderConditionsV2,locations:renderLocationsV2,instructions:renderInstructionsV2,assistants:renderAssistantsV2,message:renderMessageV2,attachments:renderAttachmentsV3,review:renderReview,report:renderReportV3,payment:renderPaymentGate,password:renderPasswordV3,downloads:renderDownloads}[current]??renderDashboardV5)(anchor);injectReadiness();renderFlow();decorateCustomerUI();decorateVersionUpdateUX();decorateVersionDownloads();decorateResumeChoice();if(current==='accounts')enhanceGroupedSelector();if(current.startsWith('purchase-'))bindPurchaseInfoLinks();document.querySelector('#flow-nav').dataset.diagnostics=JSON.stringify(diagnostics());persistDraft();if(!anchor)window.scrollTo({top:resetScroll?0:scrollY,behavior:'auto'});}
function resolvedModules(){const projected=projectDashboard(store,receipt,{platformTemplates:templates}).module_cards.filter(card=>card.state==='COMPLETE').map(card=>card.module_id);return new Set([...projected,...Object.entries(v3State.module_resolutions).filter(([,value])=>value).map(([key])=>key)]);}
function renderFlow(){const modules=flow.slice(0,6),resumingEncryptedCheckpoint=Boolean(currentOperation&&artifacts&&resumeCheckpointPassword),completed=resumingEncryptedCheckpoint?new Set(modules):resolvedModules(),isGuide=['guide','module-detail'].includes(current),isPurchase=current.startsWith('purchase-');document.body.classList.toggle('pre-map-view',['dashboard','before','guide','module-detail'].includes(current));document.body.classList.toggle('guide-view',isGuide);document.body.classList.toggle('purchase-view',isPurchase);const nav=document.querySelector('#flow-nav');nav.innerHTML=isGuide||isPurchase?'':modules.map((id,index)=>`<button data-step="${index+1}" data-flow="${id}" class="${current===id?'active ':''}${completed.has(id)?'complete':''}">${labels[id]}</button>`).join('');nav.querySelectorAll('[data-flow]').forEach(node=>node.onclick=()=>{try{if(flow.slice(0,6).includes(current))saveVisibleModule();appState.review_context=null;navTo(node.dataset.flow);}catch(error){show(productErrorMessage(error));}});document.querySelector('#app-home').onclick=()=>{try{if(flow.slice(0,6).includes(current))saveVisibleModule();appState.review_context=null;navTo(isGuide?'guide':'dashboard');}catch(error){show(productErrorMessage(error));}};}
function navTo(id,anchor){current=enterApplicationView(appState,id);render(anchor,{resetScroll:!anchor});if(!anchor||id==='module-detail'||id==='guide')requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'auto'}));}
recalc();

function renderDashboard(){const view=projectDashboard(store,receipt,{platformTemplates:templates});app.innerHTML=`<section class="hero"><h1>${escape(store.title)}</h1><p>一个Canonical Store、一份Validation Result。普通缺失只显示为未完成。</p><dl><div><dt>Draft revision</dt><dd>${store.draft_revision}</dd></div><div><dt>Version</dt><dd>${store.version.version_number} · ${store.version.status}</dd></div><div><dt>Generation</dt><dd>${receipt.generation_allowed?'可进入Report':'尚未完成'}</dd></div></dl></section><section class="grid">${view.module_cards.map(card=>`<article class="card ${card.incomplete_count?'issue':card.state==='COMPLETE'?'complete':''}"><span class="chip">${card.state}</span><h2>${labels[card.module_id]}</h2><p>未完成 ${card.incomplete_count} · 建议 0</p>${card.issues.map(item=>`<p>${escape(item.business_message)}</p>`).join('')}<button data-module="${card.module_id}">打开模块</button>${card.incomplete_count>2?'<button class="secondary" data-review>查看全部</button>':''}</article>`).join('')}</section><section class="card"><strong>附件 ${view.attachment_count} · 未完成 ${view.uncompleted_count}</strong></section><div class="actions"><button class="secondary" id="attachments">附件中心</button><button id="report">Recovery Report</button><button class="secondary" id="review">Review</button></div><div id="message"></div>`;document.querySelectorAll('[data-module]').forEach(node=>node.onclick=()=>nav(node.dataset.module));document.querySelectorAll('[data-review]').forEach(node=>node.onclick=()=>{current='review';render();});document.querySelector('#attachments').onclick=()=>nav('attachments');document.querySelector('#review').onclick=()=>nav('review');document.querySelector('#report').onclick=()=>nav('report');}

function accountCascadeSummary(accountId){return{conditions:selectedConditions(store,accountId).length,locations:Object.values(store.location_coverages).filter(item=>item.account_id===accountId).length,instructions:store.recovery_instructions[accountId]?.instruction_text||store.recovery_instructions[accountId]?.instruction_attachment_ids.length?1:0,attachments:Object.values(store.attachments).filter(item=>item.account_id===accountId&&item.field_or_condition_id!=='module-summary').length};}
const accountRegions=['Australia','United States','United Kingdom','EEA / European Union','Canada','Singapore','Hong Kong','Japan','South Korea','New Zealand','United Arab Emirates','Other'];
const catalogGroups=[['CEX','中心化交易所'],['DEX','去中心化交易所'],['HOT_WALLET','热钱包 / 软件钱包'],['HARDWARE_WALLET','冷钱包 / 硬件钱包']];
const catalogPlatformOrder={CEX:['binance','coinbase','bybit','okx','mexc','gate','bitget','crypto_com','kraken','kucoin','htx','upbit','bithumb','bitfinex','gemini','bitstamp','bingx','coinex','phemex','bitmart','custom_cex'],DEX:['uniswap','hyperliquid','pancakeswap','jupiter','raydium','aerodrome','curve','dydx','oneinch','orca','sushiswap','balancer','osmosis','trader_joe','camelot','quickswap','custom_dex'],HOT_WALLET:['metamask','trust_wallet','phantom','imtoken','coinbase_wallet','okx_wallet','rabby_wallet','tokenpocket','solflare','tronlink','wan'+'der','tonkeeper','keplr','xaman','core','slush','lace','nova_wallet','lobstr','bluewallet','safe','custom_hot_wallet'],HARDWARE_WALLET:['ledger','trezor','safepal','onekey','keystone','tangem','coldlar','coldcard','bitbox02','foundation_passport','blockstream_jade','imkey','keepkey','ngrave','cypherock_x1','seedsigner','keypal','solflare_shield','krux','custom_hardware_wallet']};
const catalogCategoryFor=platformId=>{const category=templates.platforms.find(item=>item.id===platformId)?.category;if(['DEFI','DEX'].includes(category))return'DEX';if(['MULTISIG','HOT_WALLET'].includes(category))return'HOT_WALLET';return category;};
function removeCatalogAccount(accountId){const summary=accountCascadeSummary(accountId),hasRelated=Object.values(summary).some(Boolean),message=`取消选择将同步移除该项目的：\n恢复条件 ${summary.conditions} 项\n位置覆盖 ${summary.locations} 项\n恢复步骤 ${summary.instructions} 项\n关联附件 ${summary.attachments} 个\n\n是否继续？`,remove=versionUpdateContext?removeVersionUpdateAccount:ProductActions.removeAccount;if((!hasRelated||confirm(message))&&act(()=>remove(store,accountId,{confirmCascade:true,expected_revision:store.draft_revision})))render();}
function isAccountScoped(platformId){return templates.platforms.find(item=>item.id===platformId)?.category==='CEX';}
function addCatalogAccount(platform,{customName=''}={}){const name=customName||platform.name,platformId=platform.id,scoped=isAccountScoped(platformId);if(act(()=>ProductActions.addAccount(store,{account_id:uid('account'),platform_id:platformId,platform_name:name,region:scoped?'':'Other',account_type:scoped?'':'Personal',display_label:customName?customName:''},{expected_revision:store.draft_revision})))render();}
function toggleCatalogCategory(category){if(catalogCategory===category)catalogExpanded=!catalogExpanded;else{catalogCategory=category;catalogExpanded=true;}render();requestAnimationFrame(()=>{const row=document.querySelector(`[data-category-row="${CSS.escape(category)}"]`);if(!row)return;row.scrollIntoView({block:'start',behavior:'auto'});row.querySelector('[data-catalog-category]')?.focus({preventScroll:true});});}
function renderAccountsV4(anchor){const generated=store.version.status==='GENERATED',accounts=Object.values(store.accounts),visiblePlatforms=templates.platforms.filter(item=>item.id!=='custom'&&(catalogCategory==='ALL'||item.category===catalogCategory)),selectedIds=new Set(accounts.map(account=>account.platform_id));app.innerHTML=`<section class="module-heading"><p class="eyebrow">MODULE 1 OF 6</p><h1>资产与账户</h1><p>选择需要纳入Recovery Map的平台、钱包或协议。可多选，也可添加自定义项目。</p></section><section class="security-note"><strong>只记录恢复路径，不记录秘密。</strong><span>请勿填写私钥、助记词、OTP、Authenticator Seed或完整密码。</span></section>${generated?'<section class="card issue"><p>当前版本已生成。需要修改时，请基于此版本创建新草稿。</p><button id="derive-draft">创建新草稿并修改</button></section>':`<section class="catalog card"><div class="catalog-head"><div><h2>添加资产或账户</h2><p>按类别浏览，或搜索平台与钱包名称。</p></div><label class="catalog-search">搜索<input id="catalog-search" type="search" placeholder="例如 Binance、MetaMask、Ledger"></label></div><div class="catalog-tabs">${catalogGroups.map(([id,label])=>`<button class="secondary ${catalogCategory===id?'active':''}" data-catalog-category="${id}">${label}</button>`).join('')}</div><div class="catalog-grid">${visiblePlatforms.map(item=>{const account=accounts.find(value=>value.platform_id===item.id);return`<button class="catalog-choice ${account?'selected':''}" data-catalog-platform="${item.id}" data-search="${escape(`${item.name} ${item.category}`.toLowerCase())}" aria-pressed="${Boolean(account)}"><span class="catalog-check">${account?'✓':''}</span><strong>${escape(item.name)}</strong><small>${account?'已选择':'点击选择'}</small></button>`;}).join('')}${catalogCategory==='ALL'||catalogCategory==='CUSTOM'?`<button class="catalog-choice custom-choice" id="show-custom"><span class="catalog-check">＋</span><strong>自定义项目</strong><small>添加平台、钱包或协议</small></button>`:''}</div>${customCatalogVisible?`<div class="custom-catalog"><label class="field">自定义名称<input id="custom-catalog-name" placeholder="请输入平台、钱包或协议名称"></label><div class="actions"><button id="add-custom-catalog">添加到Recovery Map</button><button class="secondary" id="cancel-custom-catalog">取消</button></div></div>`:''}</section>`}<section class="selected-accounts"><div class="section-title"><h2>已选择 ${accounts.length} 项</h2><p>每个项目继续沿用冻结V2的地区、账户类型、备注及账户隔离规则。</p></div>${accounts.map(account=>`<fieldset data-anchor="accounts:${account.account_id}:platform_id"><legend>${escape(accountLabel(account,templates))}</legend><div class="account-fields"><label class="field">平台或钱包<input value="${escape(account.platform_name||platformName(account.platform_id))}" disabled></label><label class="field">地区<select data-account="${account.account_id}" data-key="region" ${generated?'disabled':''}><option value="">请选择</option>${accountRegions.map(value=>`<option ${account.region.value===value?'selected':''}>${value}</option>`).join('')}</select></label><label class="field">账户类型<select data-account="${account.account_id}" data-key="account_type" ${generated?'disabled':''}><option value="">请选择</option><option value="Personal" ${account.account_type.value==='Personal'?'selected':''}>个人账户</option><option value="Institutional" ${account.account_type.value==='Institutional'?'selected':''}>机构账户</option></select></label><label class="field">备注名称（选填）<input data-account="${account.account_id}" data-key="display_label" value="${escape(account.display_label)}" ${generated?'disabled':''}></label></div>${generated?'':`<button class="danger" data-remove-account="${account.account_id}">删除账户</button>`}</fieldset>`).join('')||'<section class="card muted">尚未选择任何项目。</section>'}</section>${back()}`;
document.querySelector('#derive-draft')?.addEventListener('click',()=>{store=createDraftFromVersion(store,{draftId:uid('draft')});recalc();render();});document.querySelectorAll('[data-catalog-category]').forEach(node=>node.onclick=()=>{catalogCategory=node.dataset.catalogCategory;render();});document.querySelector('#catalog-search')?.addEventListener('input',event=>{const query=event.target.value.trim().toLowerCase();document.querySelectorAll('[data-catalog-platform]').forEach(node=>node.hidden=!node.dataset.search.includes(query));});document.querySelectorAll('[data-catalog-platform]').forEach(node=>node.onclick=()=>{const account=accounts.find(value=>value.platform_id===node.dataset.catalogPlatform);if(account)removeCatalogAccount(account.account_id);else addCatalogAccount(templates.platforms.find(item=>item.id===node.dataset.catalogPlatform));});document.querySelector('#show-custom')?.addEventListener('click',()=>{customCatalogVisible=true;render();});document.querySelector('#cancel-custom-catalog')?.addEventListener('click',()=>{customCatalogVisible=false;render();});document.querySelector('#add-custom-catalog')?.addEventListener('click',()=>{const value=document.querySelector('#custom-catalog-name').value.trim();if(!value){show('请输入自定义平台、钱包或协议名称。');return;}addCatalogAccount(templates.platforms.find(item=>item.id==='custom'),{customName:value});customCatalogVisible=false;});document.querySelectorAll('[data-account]').forEach(node=>node.onchange=()=>{const key=node.dataset.key,value=node.value;if(act(()=>ProductActions.updateAccount(store,node.dataset.account,{[key]:value},{expected_revision:store.draft_revision})))render();});document.querySelectorAll('[data-remove-account]').forEach(node=>node.onclick=()=>removeCatalogAccount(node.dataset.removeAccount));focus(anchor);}
function renderAccounts(anchor){const generated=store.version.status==='GENERATED';app.innerHTML=`<h1>资产与账户</h1><p>有哪些账户、钱包或存储载体需要恢复？</p>${generated?'<section class="card issue"><p>当前版本已生成。需要修改时，请基于此版本创建新草稿。</p><button id="derive-draft">创建新草稿并修改</button></section>':''}${Object.values(store.accounts).map(account=>`<fieldset data-anchor="accounts:${account.account_id}:platform_id"><legend>${escape(accountLabel(account,templates))}</legend><label class="field">平台<select data-account="${account.account_id}" data-key="platform_id" ${generated?'disabled':''}>${templates.platforms.map(item=>`<option value="${item.id}" ${item.id===account.platform_id?'selected':''}>${item.name}</option>`).join('')}</select></label><label class="field">地区<select data-account="${account.account_id}" data-key="region" ${generated?'disabled':''}><option value="">请选择</option>${accountRegions.map(value=>`<option ${account.region.value===value?'selected':''}>${value}</option>`).join('')}</select></label><label class="field">账户类型<select data-account="${account.account_id}" data-key="account_type" ${generated?'disabled':''}><option value="">请选择</option><option value="Personal" ${account.account_type.value==='Personal'?'selected':''}>个人账户</option><option value="Institutional" ${account.account_type.value==='Institutional'?'selected':''}>机构账户</option></select></label><label class="field">备注名称（选填）<input data-account="${account.account_id}" data-key="display_label" value="${escape(account.display_label)}" ${generated?'disabled':''}></label>${generated?'':'<button class="danger" data-remove-account="'+account.account_id+'">删除账户</button>'}</fieldset>`).join('')||'<p>尚未添加账户。</p>'}${generated?'':pendingAccountVisible?`<section class="card" id="pending-account-card"><h2>新增账户</h2><label class="field">平台<select id="new-platform"><option value="">请选择</option>${templates.platforms.map(item=>`<option value="${item.id}">${item.name}</option>`).join('')}</select></label><label class="field">地区<select id="new-region"><option value="">请选择</option><option>Australia</option><option>New Zealand</option><option>United States</option><option>EEA</option><option>United Kingdom</option><option>Other</option></select></label><label class="field">账户类型<select id="new-type"><option value="">请选择</option><option value="Personal">个人账户</option><option value="Institutional">机构账户</option></select></label><label class="field">备注名称（选填）<input id="new-label"></label><div class="actions"><button id="add-account">添加账户</button><button class="secondary" id="cancel-pending">取消新增</button></div></section>`:'<button id="show-pending">新增账户</button>'}${back()}`;
document.querySelector('#derive-draft')?.addEventListener('click',()=>{store=createDraftFromVersion(store,{draftId:uid('draft')});pendingAccountVisible=false;recalc();render();});document.querySelector('#show-pending')?.addEventListener('click',()=>{pendingAccountVisible=true;render();});document.querySelector('#add-account')?.addEventListener('click',()=>{try{const committed=addPendingAccount(store);if(committed.added){store=committed.store;pendingAccountVisible=false;recalc();render();}}catch(error){show(productErrorMessage(error));}});document.querySelector('#cancel-pending')?.addEventListener('click',()=>{const input=pendingAccountInput();if(Object.values(input).some(value=>String(value).trim())&&!confirm('已填写的未保存内容将被清除，是否继续？'))return;pendingAccountVisible=false;render();});document.querySelectorAll('[data-account]').forEach(node=>node.onchange=()=>{const key=node.dataset.key,value=node.value,change={[key]:value};if(key==='platform_id')change.platform_name=platformName(value);act(()=>ProductActions.updateAccount(store,node.dataset.account,change,{expected_revision:store.draft_revision}));render();});document.querySelectorAll('[data-remove-account]').forEach(node=>node.onclick=()=>{const id=node.dataset.removeAccount,summary=accountCascadeSummary(id),message=`删除此账户将同步移除：\n恢复条件 ${summary.conditions} 项\n位置覆盖 ${summary.locations} 项\n恢复步骤 ${summary.instructions} 项\n账户关联附件 ${summary.attachments} 个\n\n是否继续？`;if(confirm(message)&&act(()=>ProductActions.removeAccount(store,id,{confirmCascade:true,expected_revision:store.draft_revision})))render();});focus(anchor);}

function renderConditions(anchor){app.innerHTML=`<h1>恢复所需条件与资料</h1><p>每个账户只显示一张汇总卡；只记录秘密存在性，不填写原文。</p>${Object.values(store.accounts).map(account=>{const selected=selectedConditions(store,account.account_id),template=templates.platforms.find(item=>item.id===account.platform_id);return`<fieldset data-anchor="conditions:${account.account_id}:selected_condition_ids"><legend>${escape(accountLabel(account,templates))}</legend>${(template?.conditions??['other']).map(id=>`<label class="choice"><input type="checkbox" data-condition-account="${account.account_id}" value="${id}" ${selected.includes(id)?'checked':''}>${conditionLabel(id)}</label>`).join('')}<label class="field">补充备注（选填）<textarea data-notes="${account.account_id}">${escape(store.condition_selections[account.account_id].optional_notes)}</textarea></label></fieldset>`;}).join('')||`<p>${dependentModuleEmptyPrompt}</p>`}${back()}`;document.querySelectorAll('[data-condition-account]').forEach(node=>node.onchange=()=>{const id=node.dataset.conditionAccount,ids=[...document.querySelectorAll(`[data-condition-account="${id}"]:checked`)].map(item=>item.value);act(()=>ProductActions.setConditionSelection(store,id,{selected_condition_ids:ids},{expected_revision:store.draft_revision}));render();});document.querySelectorAll('[data-notes]').forEach(node=>node.onchange=()=>act(()=>ProductActions.setConditionSelection(store,node.dataset.notes,{selected_condition_ids:selectedConditions(store,node.dataset.notes),optional_notes:node.value},{expected_revision:store.draft_revision})));focus(anchor);}

function fileCards(files){return files.map(file=>`<article class="card uploaded-file"><strong>${escape(file.file_name)}</strong><p>${attachmentFriendlyType(file)} · ${formatBytes(file.byte_length)} · ${escape(file.purpose)}</p><p>覆盖：${file.covered_condition_ids.map(conditionLabel).join('、')||'本模块资料'}</p><div class="actions"><label class="button secondary">替换文件<input class="hidden" type="file" data-replace-file="${file.attachment_id}"></label><button class="danger" data-delete-file="${file.attachment_id}">删除附件</button></div></article>`).join('');}
function bindFileManagement(){document.querySelectorAll('[data-delete-file]').forEach(node=>node.onclick=()=>{try{store=removeAttachment(store,node.dataset.deleteFile);recalc();render();}catch(error){showBusinessError(error);}});document.querySelectorAll('[data-replace-file]').forEach(node=>node.onchange=async()=>{if(!node.files[0])return;try{store=await replaceAttachment(store,node.dataset.replaceFile,{file:node.files[0],file_name:node.files[0].name,mime_type:node.files[0].type,byte_length:node.files[0].size},{rules,policy:attachmentPolicy});recalc();render();}catch(error){showBusinessError(error);}});}
function renderLocations(anchor){app.innerHTML=`<h1>位置与查找</h1><p>可以用一份汇总说明覆盖多项，也可以逐项填写；上传附件时只需选择它覆盖的恢复条件。</p>${Object.values(store.accounts).map(account=>{const selected=selectedConditions(store,account.account_id),coverages=Object.values(store.location_coverages).filter(item=>item.account_id===account.account_id),summary=coverages.find(item=>item.mode==='SUMMARY'),covered=new Set(summary?.covered_condition_ids??[]),remaining=selected.filter(id=>!covered.has(id)),files=Object.values(store.attachments).filter(file=>file.account_id===account.account_id&&file.module_id==='locations');return`<section class="card"><h2>${escape(accountLabel(account,templates))}</h2><fieldset data-anchor="locations:${account.account_id}:${selected[0]??'coverage'}"><legend>汇总位置（可覆盖多项）</legend>${selected.map(id=>`<label class="choice"><input type="checkbox" data-summary-account="${account.account_id}" value="${id}" ${covered.has(id)?'checked':''}>${conditionLabel(id)}</label>`).join('')}<label class="field">汇总说明<textarea data-summary-text="${account.account_id}">${escape(summary?.description??'')}</textarea></label><button data-save-summary="${account.account_id}">保存汇总</button></fieldset>${remaining.map(id=>{const item=coverages.find(value=>value.mode==='ITEMIZED'&&value.covered_condition_ids.includes(id));return`<fieldset data-anchor="locations:${account.account_id}:${id}"><legend>${conditionLabel(id)}</legend><label class="field">位置类型<input data-location="${account.account_id}" data-condition="${id}" data-key="location_type" value="${escape(item?.location_type??'')}"></label><label class="field">位置名称<input data-location="${account.account_id}" data-condition="${id}" data-key="location_name" value="${escape(item?.location_name??'')}"></label><label class="field">查找说明<textarea data-location="${account.account_id}" data-condition="${id}" data-key="description">${escape(item?.description??'')}</textarea></label><button data-save-location="${account.account_id}" data-condition="${id}">保存此位置</button></fieldset>`;}).join('')||'<p class="complete">所选条件均由汇总记录覆盖。</p>'}<fieldset><legend>上传位置说明附件</legend><p>账户：${escape(accountLabel(account,templates))} · 用途：位置说明</p>${selected.map(id=>`<label class="choice"><input type="checkbox" data-upload-cover="${account.account_id}" value="${id}">${conditionLabel(id)}</label>`).join('')}<label class="field">选择文件<input type="file" data-location-file="${account.account_id}"></label><button data-upload-location="${account.account_id}">上传附件</button></fieldset>${fileCards(files)}</section>`;}).join('')||'<p>请先添加账户并选择条件。</p>'}${back()}`;
document.querySelectorAll('[data-save-summary]').forEach(node=>node.onclick=()=>{const id=node.dataset.saveSummary,ids=[...document.querySelectorAll(`[data-summary-account="${id}"]:checked`)].map(item=>item.value),text=document.querySelector(`[data-summary-text="${id}"]`).value,existing=Object.values(store.location_coverages).find(item=>item.account_id===id&&item.mode==='SUMMARY');try{let next=store;if(existing&&!ids.length)next=ProductActions.removeCoverage(next,existing.coverage_id,{expected_revision:next.draft_revision});else if(ids.length)next=ProductActions.upsertCoverage(next,{coverage_id:existing?.coverage_id??`summary-${id}`,account_id:id,mode:'SUMMARY',covered_condition_ids:ids,description:text,attachment_ids:existing?.attachment_ids??[]},{expected_revision:next.draft_revision});store=next;recalc();render();}catch(error){showBusinessError(error);}});
document.querySelectorAll('[data-save-location]').forEach(node=>node.onclick=()=>{const id=node.dataset.saveLocation,condition=node.dataset.condition,values=Object.fromEntries([...document.querySelectorAll(`[data-location="${id}"][data-condition="${condition}"]`)].map(item=>[item.dataset.key,item.value]));if(act(()=>ProductActions.upsertCoverage(store,{coverage_id:`item-${id}-${condition}`,account_id:id,mode:'ITEMIZED',covered_condition_ids:[condition],...values,attachment_ids:store.location_coverages[`item-${id}-${condition}`]?.attachment_ids??[]},{expected_revision:store.draft_revision})))render();});
document.querySelectorAll('[data-upload-location]').forEach(node=>node.onclick=async()=>{const accountId=node.dataset.uploadLocation,account=store.accounts[accountId],file=document.querySelector(`[data-location-file="${accountId}"]`).files[0],covers=[...document.querySelectorAll(`[data-upload-cover="${accountId}"]:checked`)].map(item=>item.value);if(!file||!covers.length)return show('请选择文件以及该附件需要覆盖的恢复条件。');try{const attachmentId=uid('attachment');store=await addAttachment(store,{attachment_id:attachmentId,file,module_id:'locations',platform_id:account.platform_id,account_id:accountId,field_or_condition_id:covers.length>1?'summary':covers[0],purpose:'位置说明',covered_condition_ids:covers},{rules});const existing=Object.values(store.location_coverages).find(item=>item.account_id===accountId&&item.mode==='SUMMARY'&&covers.every(id=>item.covered_condition_ids.includes(id)));if(existing)store=ProductActions.upsertCoverage(store,{...existing,attachment_ids:[...existing.attachment_ids,attachmentId]},{expected_revision:store.draft_revision});recalc();render();}catch(error){showBusinessError(error);}});bindFileManagement();focus(anchor);}

function renderInstructions(anchor){app.innerHTML=`<h1>恢复与转移步骤</h1><p>可以填写步骤或上传完整步骤附件；风险提示为选填。</p>${Object.values(store.accounts).map(account=>{const item=store.recovery_instructions[account.account_id];return`<fieldset data-anchor="instructions:${account.account_id}:instruction"><legend>${escape(accountLabel(account,templates))}</legend><label class="field">恢复与转移步骤<textarea data-instruction="${account.account_id}" data-key="instruction_text">${escape(item.instruction_text)}</textarea></label><label class="field">风险提示（选填）<textarea data-instruction="${account.account_id}" data-key="optional_risk_notes">${escape(item.optional_risk_notes)}</textarea></label><button data-save-instruction="${account.account_id}">${item.saved_at?'已保存，再次保存更新':'保存该账户'}</button></fieldset>`;}).join('')||'<p>请先添加账户。</p>'}${back()}`;document.querySelectorAll('[data-save-instruction]').forEach(node=>node.onclick=()=>{const accountId=node.dataset.saveInstruction,fields=[...document.querySelectorAll(`[data-instruction="${accountId}"]`)],changes=Object.fromEntries(fields.map(field=>[field.dataset.key,field.value]));let next=store;try{next=ProductActions.updateInstruction(next,accountId,changes,{expected_revision:next.draft_revision});next=ProductActions.confirmInstructionSaved(next,accountId,{expected_revision:next.draft_revision});store=next;recalc();render();}catch(error){show(error.message);}});focus(anchor);}

function renderAssistants(anchor){app.innerHTML=`<h1>协助人</h1><p>整体选填。任何协助人都不应集中掌握全部控制材料。</p><label class="field">是否需要协助<select id="decision"><option value="NOT_SET">未设置</option><option value="NEED" ${store.assistant_decision==='NEED'?'selected':''}>需要</option><option value="NOT_NEEDED" ${store.assistant_decision==='NOT_NEEDED'?'selected':''}>不需要</option><option value="UNKNOWN" ${store.assistant_decision==='UNKNOWN'?'selected':''}>暂不确定</option></select></label>${store.assistant_decision==='NEED'?`<fieldset data-anchor="assistants:map:assistants"><legend>协助人</legend>${['role','contact_timing','allowed_help','permission_boundary'].map(key=>`<label class="field">${({role:'角色',contact_timing:'联系时机',allowed_help:'可协助事项',permission_boundary:'权限边界'})[key]}<input data-assistant-key="${key}" value="${escape(Object.values(store.assistants)[0]?.[key]??'')}"></label>`).join('')}</fieldset>`:''}${back()}`;document.querySelector('#decision').onchange=event=>{act(()=>ProductActions.setAssistantDecision(store,event.target.value,{expected_revision:store.draft_revision}));render();};focus(anchor);}

function renderMessage(){app.innerHTML=`<h1>给未来恢复人的嘱托</h1><p>完全选填，不影响生成。</p><label class="field">留言<textarea id="personal-message">${escape(store.personal_message?.text??'')}</textarea></label>${back()}`;focus();}

function renderAttachments(){const capacity=attachmentCapacity(store,rules),moduleNames={locations:'位置与查找',instructions:'恢复与转移步骤',accounts:'账户识别',conditions:'恢复条件',assistants:'协助人',message:'个人嘱托'};app.innerHTML=`<h1>附件中心</h1><p>普通流程可在对应模块直接上传；这里用于统一查看、替换和删除。</p><section class="card"><label class="field">附件属于哪个账户？<select id="file-account"><option value="">请选择账户</option>${Object.values(store.accounts).map(item=>`<option value="${item.account_id}">${escape(accountLabel(item,templates))}</option>`).join('')}</select></label><label class="field">附件用于什么？<select id="file-module"><option value="locations">位置说明</option><option value="instructions">恢复步骤</option><option value="accounts">账户识别资料</option><option value="conditions">恢复条件说明</option><option value="assistants">协助人说明</option><option value="message">个人嘱托</option></select></label><label class="field">具体用途<select id="file-purpose"><option>位置说明</option><option>恢复操作说明</option><option>账户识别</option><option>辅助证据</option><option>个人留言</option></select></label>${Object.values(store.accounts).map(account=>`<fieldset hidden data-file-conditions="${account.account_id}"><legend>需要覆盖哪些恢复条件？</legend>${selectedConditions(store,account.account_id).map(id=>`<label class="choice"><input type="checkbox" value="${id}">${conditionLabel(id)}</label>`).join('')||'<p>该账户尚未选择恢复条件。</p>'}</fieldset>`).join('')}<label class="field">选择文件<input type="file" id="file-upload"></label><button id="upload">上传附件</button></section>${Object.values(store.attachments).map(file=>`<article class="card"><strong>${escape(file.file_name)}</strong><p>账户：${escape(accountLabel(store.accounts[file.account_id],templates))}</p><p>${escape(moduleNames[file.module_id])} · ${escape(file.purpose)} · ${formatBytes(file.byte_length)} · ${attachmentFriendlyType(file)}</p><p>覆盖：${file.covered_condition_ids.map(conditionLabel).join('、')||'本模块资料'}</p><div class="actions"><button class="secondary" data-view-file="${file.attachment_id}">查看/下载</button><label class="button secondary">替换文件<input class="hidden" type="file" data-replace-file="${file.attachment_id}"></label><button class="danger" data-delete-file="${file.attachment_id}">删除附件</button></div></article>`).join('')||'<p>暂无附件。</p>'}<p class="capacity">已用 ${capacity.used_bytes} bytes · 剩余 ${capacity.remaining_bytes} bytes · ${capacity.count}/${rules.limits.max_attachments}</p>${back()}`;
const accountSelect=document.querySelector('#file-account'),moduleSelect=document.querySelector('#file-module'),syncChoices=()=>{document.querySelectorAll('[data-file-conditions]').forEach(node=>node.hidden=node.dataset.fileConditions!==accountSelect.value);};accountSelect.onchange=syncChoices;syncChoices();document.querySelector('#upload').onclick=async()=>{const accountId=accountSelect.value,moduleId=moduleSelect.value,file=document.querySelector('#file-upload').files[0],scope=document.querySelector(`[data-file-conditions="${accountId}"]`),covers=scope?[...scope.querySelectorAll('input:checked')].map(node=>node.value):[],needsCoverage=moduleId==='locations';if(!accountId||!file||(needsCoverage&&!covers.length))return show('请选择该附件所属账户、用途以及需要覆盖的恢复条件。');try{const attachmentId=uid('attachment'),purpose=document.querySelector('#file-purpose').value;store=await addAttachment(store,{attachment_id:attachmentId,file,module_id:moduleId,platform_id:store.accounts[accountId].platform_id,account_id:accountId,field_or_condition_id:needsCoverage?(covers.length>1?'summary':covers[0]):moduleId,purpose,covered_condition_ids:covers},{rules});if(moduleId==='instructions')store=ProductActions.updateInstruction(store,accountId,{instruction_attachment_ids:[...store.recovery_instructions[accountId].instruction_attachment_ids,attachmentId]},{expected_revision:store.draft_revision});if(moduleId==='message')store=ProductActions.setPersonalMessage(store,{text:store.personal_message?.text??'',attachment_ids:[...(store.personal_message?.attachment_ids??[]),attachmentId]},{expected_revision:store.draft_revision});recalc();render();}catch(error){showBusinessError(error);}};bindFileManagement();document.querySelectorAll('[data-view-file]').forEach(node=>node.onclick=()=>{const file=store.attachments[node.dataset.viewFile],url=URL.createObjectURL(new Blob([file.bytes],{type:file.mime_type})),a=document.createElement('a');a.href=url;a.download=file.file_name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});focus();}

function renderReview(anchor){
  recalc();
  const view=projectReview(store,receipt,generationPreflight),unresolved=flow.slice(0,6).filter(id=>!resolvedModules().has(id));
  const issueHtml=item=>`<article class="issue"><strong>${escape(item.business_message)}</strong><p>${escape(item.why_required)}</p><p>${escape(item.completion_method)}</p><button data-fix="${item.navigation_anchor}">返回准确修改</button></article>`;
  app.innerHTML=`<h1>检查与完善</h1><p class="subtitle">Review</p><p>我们检查了你的Recovery Map，并列出创建正式恢复版本前建议完善的内容。</p>${view.groups.map(group=>`<section class="card" data-review-group="${group.module_id}"><h2>${labels[group.module_id]}</h2>${group.issues.map(issueHtml).join('')}</section>`).join('')}${unresolved.map(id=>`<section class="card issue" data-review-group="${id}"><h2>${labels[id]}</h2><article class="issue"><strong>此模块尚未确认完成</strong><p>请进入模块阅读填写说明，完成填写或明确选择暂不填写。</p><button data-fix="${id}:map:completion">返回准确修改</button></article></section>`).join('')}${!view.groups.length&&!unresolved.length?'<section class="card complete">没有阻断问题。</section>':''}<div class="actions"><button class="secondary" id="review-previous">上一步</button><button class="secondary" id="back-dashboard">返回概览</button><button id="to-report" ${unresolved.length?'disabled':''}>恢复说明预览</button></div><div id="message" aria-live="polite"></div>`;
  document.querySelector('#review-previous').onclick=()=>nav('message');document.querySelector('#back-dashboard').onclick=()=>{appState.review_context=null;nav('dashboard');};document.querySelector('#to-report').onclick=()=>{appState.review_context=null;nav('report');};document.querySelectorAll('[data-fix]').forEach(node=>node.onclick=()=>{const[moduleId]=node.dataset.fix.split(':');appState.review_context={navigation_anchor:node.dataset.fix,group_module_id:moduleId,scroll_y:window.scrollY};nav(moduleId,node.dataset.fix);});const context=appState.review_context;if(context)requestAnimationFrame(()=>{const group=document.querySelector(`[data-review-group="${CSS.escape(context.group_module_id)}"]`);if(group)group.scrollIntoView({block:'center'});else window.scrollTo(0,context.scroll_y??0);});focus(anchor);
}

function renderReport(){report=projectReport(store,receipt,{platformTemplates:templates,mode:'PREVIEW_EDITABLE'});const gate=generationGate(store,receipt,report);app.innerHTML=`<h1>Recovery Report / Manual</h1><section class="card"><dl><div><dt>名称</dt><dd>${escape(report.title)}</dd></div><div><dt>Version</dt><dd>${report.version_number}</dd></div><div><dt>账户</dt><dd>${report.account_count}</dd></div><div><dt>附件</dt><dd>${report.attachment_count}</dd></div><div><dt>状态</dt><dd>${report.completion_status}</dd></div></dl></section>${report.accounts.map(account=>`<section class="card report-account"><h2>${escape(account.label)}</h2><p>${escape(account.region)} · ${escape(account.account_type)}</p><h3>恢复条件和位置</h3>${account.conditions.map(item=>`<p><span class="chip">${escape(item.label)}</span>${item.coverage.map(value=>`${escape(value.mode)} · ${escape(value.location_name||value.description||'附件覆盖')}`).join('')||'未完成'}</p>`).join('')}<h3>恢复与转移步骤</h3><p>${escape(account.instruction.instruction_text||'使用步骤附件')}</p>${account.instruction.optional_risk_notes?`<p>风险提示：${escape(account.instruction.optional_risk_notes)}</p>`:''}<p>附件 ${account.attachments.length}</p><button data-edit-account="${account.account_id}">修改账户</button></section>`).join('')}<section class="card"><h2>协助人</h2><p>${escape(store.assistant_decision)}</p><h2>个人嘱托</h2><p>${escape(store.personal_message?.text??'未填写')}</p><h2>附件目录</h2>${report.attachment_directory.map(file=>`<p>${escape(file.file_name)} · ${escape(file.account_id)} · ${escape(file.purpose)}</p>`).join('')||'<p>无附件</p>'}</section>${report.issues.length?`<section class="card issue"><h2>未完成</h2>${report.issues.map(item=>`<p>${escape(item.business_message)}</p>`).join('')}</section>`:''}<div class="actions"><button class="secondary" id="report-back">返回Dashboard</button><button class="secondary" id="report-review">Review</button><button id="password" ${gate.allowed?'':'disabled'}>设置密码并生成</button></div>`;document.querySelector('#report-back').onclick=()=>nav('dashboard');document.querySelector('#report-review').onclick=()=>nav('review');document.querySelector('#password').onclick=()=>nav('password');document.querySelectorAll('[data-edit-account]').forEach(node=>node.onclick=()=>nav('accounts',`accounts:${node.dataset.editAccount}:platform_id`));}

function renderPassword(){app.innerHTML=`<h1>设置恢复密码</h1><section class="card"><label class="field">恢复密码<input id="password-value" type="password" autocomplete="new-password"></label><label class="field">确认密码<input id="password-confirm" type="password" autocomplete="new-password"></label><label class="choice"><input id="ack" type="checkbox">我理解平台无法找回恢复密码</label><p id="password-status"></p><button id="generate" disabled>创建安全恢复版本</button></section><section class="card process-status" aria-live="polite"><h2>创建进度</h2><ol id="generation-stages"><li>准备恢复版本</li><li>浏览器本地加密</li><li>生成恢复材料</li><li>完成</li></ol><p id="generation-status">等待开始；本地验收不会执行付款、钱包签名或Mainnet广播。</p></section><button class="secondary" id="back-report">返回预览</button><div id="message"></div>`;const update=()=>{const result=validateRecoveryPassword(document.querySelector('#password-value').value,document.querySelector('#password-confirm').value,document.querySelector('#ack').checked,{policy:passwordPolicy,vaultName:store.title});document.querySelector('#password-status').textContent=`${result.status} · ${result.issues.map(item=>item.message).join('；')}`;document.querySelector('#generate').disabled=!result.valid;};const stage=index=>{document.querySelectorAll('#generation-stages li').forEach((node,i)=>node.className=i<index?'done':i===index?'active':'');};document.querySelectorAll('input').forEach(node=>{node.onkeydown=event=>{if(event.key==='Enter')event.preventDefault();};node.oninput=update;node.onchange=update;});document.querySelector('#back-report').onclick=()=>nav('report');document.querySelector('#generate').onclick=async()=>{const button=document.querySelector('#generate'),status=document.querySelector('#generation-status');button.disabled=true;try{stage(0);status.textContent='正在准备Recovery Map并执行最终检查…';const fresh=validateProductStore(store,{platformTemplates:templates,rules}),freshReport=projectReport(store,fresh,{platformTemplates:templates}),gate=generationGate(store,fresh,freshReport);if(!gate.allowed)throw new Error('当前Recovery Map未通过统一Generation Gate。');const ready=markReviewReady(store,fresh),knowledge=mapProductToKnowledgeV2(ready,fresh,{platformTemplates:templates}),snapshotId=`v2-${crypto.randomUUID()}`,password=document.querySelector('#password-value').value;stage(1);status.textContent='正在当前浏览器内加密，不会上传密码或明文资料…';artifacts=await createVaultArtifacts({knowledgeGraph:knowledge,attachmentPayloads:attachmentPayloads(ready),password,wizardConfigVersion:2,vaultId:'v2-local-vault',snapshotId,createdAt:new Date().toISOString()});document.querySelector('#password-value').value='';document.querySelector('#password-confirm').value='';stage(2);status.textContent='加密完成，正在准备Recovery Kit与本地加密备份…';store=markGenerated(ready,fresh);receipt=fresh;stage(3);status.textContent='安全恢复版本已创建。';current='downloads';render();}catch(error){button.disabled=false;stage(-1);status.textContent='创建未完成，请按提示修正后重试。';show(error.message);}};update();}

function renderDownloads(){if(!publishMaterialsReady(currentOperation,mainnetEvidence)){current='password';renderPasswordV3();setPublishSafetyLock(true);setGenerationStage(3,'安全存储尚未完成验证，最终恢复材料暂不可下载。');return;}const snapshotId=artifacts.snapshot.snapshot_id,evidenceBytes=new TextEncoder().encode(JSON.stringify(mainnetEvidence,null,2));app.innerHTML=`<div class="completion-check" aria-hidden="true">✓</div><p class="eyebrow">RECOVERY VERSION CREATED</p><h1>安全恢复版本 ${store.version.version_number} 已创建</h1><p>Mainnet可读取性、Archive大小与SHA-256完整性验证均已通过。</p><section class="card"><h2>Recovery Kit</h2><p>独立恢复必需，请与Recovery Password分开保管。</p><button id="kit">保存Recovery Kit</button><p id="kit-status">尚未保存</p></section><section class="card"><h2>Mainnet Recovery Evidence</h2><p>独立恢复必需，用于从长期存储网络取得本次加密恢复版本。</p><button id="evidence">保存Mainnet Recovery Evidence</button><p id="evidence-status">尚未保存</p></section><section class="card"><h2>Local Encrypted Backup</h2><p>可选本地加密备份，不是Mainnet独立恢复的必需文件。</p><button id="archive">保存Local Encrypted Backup</button><p id="archive-status">尚未保存</p></section><section class="card"><h2>完成前请确认</h2><p>请安全保存并分开保管以下恢复材料：</p><ul><li id="kit-check">Recovery Kit 尚未保存</li><li id="evidence-check">Mainnet Recovery Evidence 尚未保存</li><li>Recovery Password 已由你单独安全保管</li></ul></section><div class="actions"><a class="button" href="${canonicalRecoveryUrl('post-creation')}" target="_blank">打开独立恢复</a></div>`;for(const[kind,data,name,mime]of[['kit',artifacts.kitBytes,`Recovery-Kit-LEGAVIK-${snapshotId}.cjas`,'application/octet-stream'],['evidence',evidenceBytes,`Mainnet-Recovery-Evidence-LEGAVIK-${snapshotId}.json`,'application/json'],['archive',artifacts.archiveBytes,`Local-Encrypted-Backup-LEGAVIK-${snapshotId}.cjasvault`,'application/octet-stream']])document.querySelector(`#${kind}`).onclick=async()=>{const result=await saveBytesLocally({bytes:data,suggestedName:name,mimeType:mime}),saved=result.status==='saved'||result.status==='download-started';document.querySelector(`#${kind}-status`).textContent=result.status==='cancelled'?'已取消，未标记完成。':result.status==='saved'?'已保存。':'浏览器下载已开始。';document.querySelector(`#${kind}-check`)?.replaceChildren(document.createTextNode(`${kind==='kit'?'Recovery Kit':'Mainnet Recovery Evidence'}${saved?'已保存':'尚未保存'}`));};}

function back(){const source=current==='attachments'?(appState.attachment_context?.return_module??appState.attachment_context?.return_view):current,index=flow.indexOf(source),previous=index>0?flow[index-1]:'guide',continueLabel=current==='attachments'?(source?'返回原页面':'返回概览'):appState.review_context?'保存并返回 Review':'保存并继续',attachmentAction=flow.slice(0,6).includes(current)?'<button class="secondary attachment-action" id="module-attachments">添加附件</button>':'';if(current==='attachments'&&source)return`<div class="drawer-return-bar"><button id="module-continue">返回原页面</button></div><div id="message"></div><input type="hidden" id="previous-step" value="${previous}">`;return`<div class="sticky-actions"><button class="secondary" id="module-previous">上一步</button><span class="autosave-copy">✓ 当前创建进度已保存于本次会话</span>${attachmentAction}<button id="module-continue">${continueLabel}</button></div><div id="message"></div><input type="hidden" id="previous-step" value="${previous}">`;}
function saveVisibleModule(){let next=store;if(current==='accounts'){for(const account of Object.values(store.accounts)){const nodes=[...document.querySelectorAll(`[data-account="${account.account_id}"]`)],values=Object.fromEntries(nodes.map(node=>[node.dataset.key,node.value]));if(nodes.length)next=ProductActions.updateAccount(next,account.account_id,{...values,platform_name:platformName(values.platform_id)},{expected_revision:next.draft_revision});}}else if(current==='conditions'){for(const account of Object.values(store.accounts)){const ids=[...document.querySelectorAll(`[data-condition-account="${account.account_id}"]:checked`)].map(node=>node.value),notes=document.querySelector(`[data-notes="${account.account_id}"]`)?.value??'';next=ProductActions.setConditionSelection(next,account.account_id,{selected_condition_ids:ids,optional_notes:notes},{expected_revision:next.draft_revision});}}else if(current==='locations'){for(const account of Object.values(store.accounts)){for(const coverage of Object.values(next.location_coverages).filter(item=>item.account_id===account.account_id))next=ProductActions.removeCoverage(next,coverage.coverage_id,{expected_revision:next.draft_revision});const summaryIds=[...document.querySelectorAll(`[data-summary-account="${account.account_id}"]:checked`)].map(node=>node.value),summaryText=document.querySelector(`[data-summary-text="${account.account_id}"]`)?.value.trim()??'';if(summaryIds.length&&(summaryText||Object.values(store.attachments).some(file=>file.account_id===account.account_id&&file.module_id==='locations'&&file.covered_condition_ids.some(id=>summaryIds.includes(id)))))next=ProductActions.upsertCoverage(next,{coverage_id:`summary-${account.account_id}`,account_id:account.account_id,mode:'SUMMARY',covered_condition_ids:summaryIds,description:summaryText,attachment_ids:Object.values(store.attachments).filter(file=>file.account_id===account.account_id&&file.module_id==='locations'&&file.covered_condition_ids.some(id=>summaryIds.includes(id))).map(file=>file.attachment_id)},{expected_revision:next.draft_revision});const conditions=[...new Set([...document.querySelectorAll(`[data-location="${account.account_id}"]`)].map(node=>node.dataset.condition))];for(const condition of conditions){const values=Object.fromEntries([...document.querySelectorAll(`[data-location="${account.account_id}"][data-condition="${condition}"]`)].map(item=>[item.dataset.key,item.value]));if(Object.values(values).some(value=>value.trim()))next=ProductActions.upsertCoverage(next,{coverage_id:`item-${account.account_id}-${condition}`,account_id:account.account_id,mode:'ITEMIZED',covered_condition_ids:[condition],...values,attachment_ids:Object.values(store.attachments).filter(file=>file.account_id===account.account_id&&file.module_id==='locations'&&file.covered_condition_ids.includes(condition)).map(file=>file.attachment_id)},{expected_revision:next.draft_revision});}}}else if(current==='instructions'){for(const account of Object.values(store.accounts)){const fields=[...document.querySelectorAll(`[data-instruction="${account.account_id}"]`)],changes=Object.fromEntries(fields.map(field=>[field.dataset.key,field.value]));if(fields.length){next=ProductActions.updateInstruction(next,account.account_id,changes,{expected_revision:next.draft_revision});if(changes.instruction_text?.trim()||next.recovery_instructions[account.account_id].instruction_attachment_ids.length)next=ProductActions.confirmInstructionSaved(next,account.account_id,{expected_revision:next.draft_revision});}}}else if(current==='assistants'){const decision=document.querySelector('#decision')?.value??store.assistant_decision;if(decision!==next.assistant_decision)next=ProductActions.setAssistantDecision(next,decision,{expected_revision:next.draft_revision});if(decision==='NEED'){const values=Object.fromEntries([...document.querySelectorAll('[data-assistant-key]')].map(item=>[item.dataset.assistantKey,item.value])),assistantId=Object.keys(next.assistants)[0]??'assistant-main',hasValue=Object.values(values).some(value=>String(value).trim());if(hasValue)next=ProductActions.upsertAssistant(next,{assistant_id:assistantId,...values},{expected_revision:next.draft_revision});else if(next.assistants[assistantId])next=ProductActions.removeAssistant(next,assistantId,{expected_revision:next.draft_revision});}}else if(current==='message'){next=ProductActions.setPersonalMessage(next,{text:document.querySelector('#personal-message')?.value??'',attachment_ids:store.personal_message?.attachment_ids??[]},{expected_revision:next.draft_revision});}store=next;recalc();}
function clearModuleSelfCheck(){app.querySelector('.module-self-check')?.remove();app.querySelectorAll('.self-check-missing,[aria-invalid="true"]').forEach(node=>{node.classList.remove('self-check-missing');node.removeAttribute('aria-invalid');});}
function validateCurrentModuleBeforeContinue(){clearModuleSelfCheck();const issues=receipt.validation_issues.filter(item=>item.module_id===current&&item.blocking);if(!issues.length)return true;for(const issue of issues){const anchor=app.querySelector(`[data-anchor="${CSS.escape(issue.navigation_anchor)}"]`)??app.querySelector(`[data-anchor^="${CSS.escape(`${current}:${issue.account_id??''}`)}"]`),field=issue.account_id&&issue.field_id?app.querySelector(`[data-account="${CSS.escape(issue.account_id)}"][data-key="${CSS.escape(issue.field_id)}"]`):null,target=field??anchor;if(target){target.classList.add('self-check-missing');target.setAttribute('aria-invalid','true');}if(current==='locations')for(const conditionId of issue.missing_condition_ids??[issue.condition_id])app.querySelectorAll(`[data-condition="${CSS.escape(conditionId??'')}"],[value="${CSS.escape(conditionId??'')}" ]`).forEach(node=>node.closest('.choice,fieldset')?.classList.add('self-check-missing'));}const summary=document.createElement('section');summary.className='module-self-check issue';summary.setAttribute('role','alert');summary.innerHTML=`<strong>请先完成当前模块</strong><p>以下内容尚未完成，修正后再点击“${appState.review_context?'保存并返回 Review':'保存并继续'}”。</p><ul>${issues.map(item=>`<li>${escape(item.business_message)} — ${escape(item.completion_method)}</li>`).join('')}</ul>`;app.querySelector('.sticky-actions')?.before(summary);show('当前模块尚未完成，已标出需要补充的内容。');return false;}
function bindBack(){
  const previous=document.querySelector('#module-previous'),continueButton=document.querySelector('#module-continue'),attachments=document.querySelector('#module-attachments');
  if(previous)previous.onclick=()=>{try{if(current==='attachments'&&(appState.attachment_context?.return_module||appState.attachment_context?.return_view))return returnFromAttachment();if(flow.slice(0,6).includes(current))saveVisibleModule();navTo(document.querySelector('#previous-step').value);}catch(error){show(productErrorMessage(error));}};
  if(continueButton)continueButton.onclick=()=>{try{if(current==='attachments'){if(appState.attachment_context?.return_module||appState.attachment_context?.return_view)return returnFromAttachment();return navTo('dashboard');}if(current==='accounts'){const committed=addPendingAccount(store);store=committed.store;}saveVisibleModule();if(!validateCurrentModuleBeforeContinue())return;v3State.module_resolutions[current]=true;persistDraft();if(appState.review_context)return navTo('review');navTo(nextProductView(current));}catch(error){show(productErrorMessage(error));}};
  if(attachments)attachments.onclick=()=>openAttachmentCenter({module_id:current,purpose:attachmentPurposes[current]?.[0]??labels[current],source_scroll_anchor:window.scrollY});
}
function openAttachmentCenter(context={}){const returnModule=flow.slice(0,6).includes(current)?current:null;if(returnModule)saveVisibleModule();const returnView=returnModule?null:['report','review'].includes(current)?current:versionUpdateContext&&current==='dashboard'?'dashboard':null;if(returnModule&&!['assistants','message'].includes(returnModule))context={...context,account_id:null};attachmentReturnScroll=context.source_scroll_anchor??window.scrollY;document.body.style.minHeight=`${document.documentElement.scrollHeight}px`;const snapshot=app.cloneNode(true);snapshot.removeAttribute('id');snapshot.querySelectorAll('[id]').forEach(node=>node.removeAttribute('id'));snapshot.className='attachment-background-snapshot';snapshot.setAttribute('aria-hidden','true');snapshot.inert=true;document.querySelector('#overlay-root').replaceChildren(snapshot);document.body.classList.add('attachment-drawer-open');current=beginAttachmentView(appState,{...context,return_module:returnModule,return_view:returnView});render();}
function returnFromAttachment(){const target=leaveAttachmentView(appState);document.body.classList.remove('attachment-drawer-open');document.querySelector('#overlay-root').replaceChildren();current=enterApplicationView(appState,target);render();document.body.style.minHeight='';window.scrollTo({top:attachmentReturnScroll,behavior:'auto'});}
function focus(anchor){bindBack();document.querySelectorAll('[data-quick-attachment]').forEach(node=>node.onclick=()=>{try{openAttachmentCenter({account_id:node.dataset.accountId,module_id:node.dataset.moduleId,purpose:node.dataset.purpose,covered_condition_ids:(node.dataset.coveredIds??'').split(',').filter(Boolean)});}catch(error){show(productErrorMessage(error));}});if(!anchor)return;const parts=anchor.split(':'),exact=document.querySelector(`[data-anchor="${CSS.escape(anchor)}"]`),field=parts[0]==='accounts'?document.querySelector(`[data-account="${CSS.escape(parts[1])}"][data-key="${CSS.escape(parts[2])}"]`):null,node=exact??field?.closest('fieldset');if(node){node.classList.add('focus');node.scrollIntoView({block:'center'});(field??node.querySelector('input,select,textarea,button'))?.focus();}}

const MODULE_SUMMARY_SCOPE='module-summary';
const isModuleSummary=file=>file?.field_or_condition_id===MODULE_SUMMARY_SCOPE;
const isLocationModuleSummary=(scope,moduleId,purpose)=>moduleId==='locations'&&(scope===MODULE_SUMMARY_SCOPE||purpose==='汇总位置说明');
function compatibilityAttachmentAnchor(){
  // Frozen records retain a technical account reference. Public projections strip
  // it from module-summary attachments, so it never becomes product ownership.
  return Object.values(store.accounts).reduce((selected,item)=>!selected||item.account_id.localeCompare(selected.account_id)<0?item:selected,null)?.account_id??'';
}
function attachmentScopeForm(prefix,file={}){const accountId=isModuleSummary(file)?MODULE_SUMMARY_SCOPE:(file.account_id??'');return`<label class="field">附件范围<select id="${prefix}-account"><option value="" ${accountId===''?'selected':''}>请选择</option><option value="${MODULE_SUMMARY_SCOPE}" ${accountId===MODULE_SUMMARY_SCOPE?'selected':''}>本模块汇总信息</option>${Object.values(store.accounts).map(item=>`<option value="${item.account_id}" ${item.account_id===accountId?'selected':''}>${escape(accountLabel(item,templates))}</option>`).join('')}</select><small class="scope-help">该附件包含本模块需要记录的全部相关信息</small></label><label class="field">附件用于什么<select id="${prefix}-module"><option value="">请选择</option>${attachmentModules.map(([id,label])=>`<option value="${id}" ${id===file.module_id?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">具体用途<select id="${prefix}-purpose"><option value="">请选择</option></select></label><div id="${prefix}-conditions"></div>`;}
function syncAttachmentScope(prefix,file={}){const account=document.querySelector(`#${prefix}-account`),module=document.querySelector(`#${prefix}-module`),purpose=document.querySelector(`#${prefix}-purpose`),conditions=document.querySelector(`#${prefix}-conditions`);const refresh=()=>{const previous=purpose.value||file.purpose||'';purpose.innerHTML='<option value="">请选择</option>'+((attachmentPurposes[module.value]??[]).map(value=>`<option ${value===previous?'selected':''}>${value}</option>`).join(''));const moduleSummary=isLocationModuleSummary(account.value,module.value,purpose.value)||account.value===MODULE_SUMMARY_SCOPE,selected=moduleSummary?[]:selectedConditions(store,account.value);conditions.innerHTML=module.value==='locations'&&!moduleSummary?`<fieldset><legend>需要覆盖哪些恢复条件？</legend>${selected.map(id=>`<label class="choice"><input type="checkbox" value="${id}" ${(file.covered_condition_ids??[]).includes(id)?'checked':''}>${conditionLabel(id)}</label>`).join('')||'<p>该账户尚未选择恢复条件。</p>'}</fieldset>`:module.value==='locations'&&moduleSummary?'<p class="module-summary-note">“汇总位置说明”属于模块汇总附件，无需选择单项恢复条件。</p>':'';};account.onchange=refresh;module.onchange=refresh;purpose.onchange=refresh;refresh();}
function readAttachmentScope(prefix){const selectedScope=document.querySelector(`#${prefix}-account`).value,moduleId=document.querySelector(`#${prefix}-module`).value,purpose=document.querySelector(`#${prefix}-purpose`).value,moduleSummary=isLocationModuleSummary(selectedScope,moduleId,purpose)||selectedScope===MODULE_SUMMARY_SCOPE,globalModule=['assistants','message'].includes(moduleId),accountId=moduleSummary||globalModule?compatibilityAttachmentAnchor():selectedScope,covers=moduleSummary&&moduleId==='locations'?Object.values(store.accounts).flatMap(account=>selectedConditions(store,account.account_id)):[...document.querySelectorAll(`#${prefix}-conditions input:checked`)].map(node=>node.value);if(!selectedScope&&!globalModule)throw new Error('请选择附件范围。');if(!accountId||!moduleId||!purpose||(moduleId==='locations'&&!moduleSummary&&!covers.length))throw new Error('请选择该附件所属模块、用途以及需要覆盖的恢复条件。');return{account_id:accountId,platform_id:store.accounts[accountId].platform_id,module_id:moduleId,purpose,covered_condition_ids:moduleSummary?[]:covers,field_or_condition_id:moduleSummary?MODULE_SUMMARY_SCOPE:moduleId==='locations'?(covers.length>1?'summary':covers[0]):moduleId};}
function renderAttachmentsV2(){const capacity=attachmentCapacity(store,attachmentPolicy),categoryCounts={文档:0,图片:0,音频:0,视频:0,其它:0};for(const file of Object.values(store.attachments)){const category=classifyAttachment({name:file.file_name,type:file.mime_type},attachmentPolicy)?.category??'其它';if(category==='文档')categoryCounts.文档++;else if(category==='图片')categoryCounts.图片++;else if(category.includes('语音'))categoryCounts.音频++;else if(category.includes('视频'))categoryCounts.视频++;else categoryCounts.其它++;}app.innerHTML=`<h1>附件中心</h1><p>统一查看和管理附件；普通流程仍可在对应模块直接上传。</p><section class="card attachment-overview"><h2>附件概览</h2><div class="attachment-stats"><span>文档：${categoryCounts.文档}</span><span>图片：${categoryCounts.图片}</span><span>音频：${categoryCounts.音频}</span><span>视频：${categoryCounts.视频}</span><span>其它：${categoryCounts.其它}</span></div><p>已使用：${formatBytes(capacity.used_bytes)} · 总容量：${formatBytes(attachmentPolicy.limits.max_version_bytes)} · 剩余：${formatBytes(capacity.remaining_bytes)} · 附件数量：${capacity.count} / ${attachmentPolicy.limits.max_attachments}</p></section><section class="card upload-card"><h2>上传新附件</h2>${uploadPolicyNotice()}${attachmentScopeForm('new-file')}<label class="field">选择文件<input type="file" id="file-upload" accept="${attachmentAccept}"></label><button id="upload">上传附件</button></section><section><h2>已上传附件</h2>${Object.values(store.attachments).map(file=>`<article class="card uploaded-file" data-attachment-card="${file.attachment_id}"><strong>${escape(file.file_name)}</strong><p>${attachmentFriendlyType(file)} · ${formatBytes(file.byte_length)}</p><p>所属账户：${escape(accountLabel(store.accounts[file.account_id],templates))} · 所属模块：${escape(attachmentModules.find(([id])=>id===file.module_id)?.[1]??file.module_id)} · 具体用途：${escape(file.purpose)}</p><button class="secondary" data-edit-toggle="${file.attachment_id}">修改归属</button><div class="hidden" data-edit-panel="${file.attachment_id}">${attachmentScopeForm(`edit-${file.attachment_id}`,file)}<button data-save-scope="${file.attachment_id}">保存归属</button></div><div class="actions"><button class="secondary" data-view-file="${file.attachment_id}">查看/下载</button><label class="button secondary">替换文件<input class="hidden" type="file" data-replace-file="${file.attachment_id}" accept="${attachmentAccept}"></label><button class="danger" data-delete-file="${file.attachment_id}">删除附件</button></div></article>`).join('')||'<p>暂无附件。</p>'}</section><p class="capacity">已使用：${formatBytes(capacity.used_bytes)} / ${Math.round(attachmentPolicy.limits.max_version_bytes/1048576)} MB · 附件数量：${capacity.count} / ${attachmentPolicy.limits.max_attachments} · 单文件上限：${Math.round(attachmentPolicy.limits.max_attachment_bytes/1048576)} MB</p>${back()}`;syncAttachmentScope('new-file');for(const file of Object.values(store.attachments))syncAttachmentScope(`edit-${file.attachment_id}`,file);document.querySelectorAll('[data-edit-toggle]').forEach(node=>node.onclick=()=>document.querySelector(`[data-edit-panel="${node.dataset.editToggle}"]`).classList.toggle('hidden'));document.querySelector('#upload').onclick=async()=>{const file=document.querySelector('#file-upload').files[0];if(!file)return show('请选择需要上传的文件。');try{store=await addAttachment(store,{attachment_id:uid('attachment'),file,...readAttachmentScope('new-file')},{rules,policy:attachmentPolicy});recalc();render();}catch(error){if(error.message?.startsWith('请选择'))show(error.message);else showBusinessError(error);}};document.querySelectorAll('[data-save-scope]').forEach(node=>node.onclick=()=>{try{store=reassignAttachment(store,node.dataset.saveScope,readAttachmentScope(`edit-${node.dataset.saveScope}`));recalc();render();}catch(error){show(error.message.startsWith('请选择')?error.message:'附件归属未能保存，请检查后重试。');}});bindFileManagement();document.querySelectorAll('[data-view-file]').forEach(node=>node.onclick=()=>{const file=store.attachments[node.dataset.viewFile],url=URL.createObjectURL(new Blob([file.bytes],{type:file.mime_type})),a=document.createElement('a');a.href=url;a.download=file.file_name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});focus();}

function reportAttachment(file){return`<article><strong>${escape(file.file_name)}</strong><p>${attachmentFriendlyType(file)} · ${formatBytes(file.byte_length)}</p><p>${file.account_id?`所属账户：${escape(file.account_label)} · `:''}所属模块：${escape(file.module_label)}</p>${file.purpose?`<p>具体用途：${escape(file.purpose)}</p>`:''}<div class="actions"><button class="secondary" data-view-file="${file.attachment_id}">查看/下载</button><button class="secondary" data-manage-file="${file.attachment_id}">管理此附件</button></div></article>`;}
function renderReportV2(){report=projectReport(store,receipt,{platformTemplates:templates,mode:'PREVIEW_EDITABLE'});const gate=generationGate(store,receipt,report),sections=new Set(report.attachment_directory.map(file=>file.module_id));app.innerHTML=`<h1>Recovery Report / Manual</h1><section class="card"><dl><div><dt>地图名称</dt><dd>${escape(report.title)}</dd></div><div><dt>Version</dt><dd>${report.version_number}</dd></div><div><dt>账户数量</dt><dd>${report.account_count}</dd></div><div><dt>平台数量</dt><dd>${report.platform_count}</dd></div><div><dt>恢复条件数量</dt><dd>${report.condition_count}</dd></div><div><dt>附件数量</dt><dd>${report.attachment_count}</dd></div></dl></section>${report.accounts.map(account=>`<section class="card report-account"><h2>${escape(account.label)}</h2><h3>1. 账户信息</h3><p>${escape(account.platform)} · ${escape(account.region)} · ${escape(account.account_type)}</p><h3>2. 恢复需要准备</h3>${account.conditions.map(item=>`<p><strong>${escape(item.label)}</strong></p>`).join('')||'<p>未填写</p>'}<h3>3. 位置与查找</h3>${account.conditions.map(item=>`<p>${escape(item.label)}：${item.coverage.map(value=>`${escape(value.mode)} · ${escape(value.location_name||value.description||'使用相关附件')}`).join('；')||'未完成'}</p>`).join('')}<h3>4. 恢复与转移步骤</h3><p>${escape(account.instruction.instruction_text||'使用相关步骤附件')}</p><h3>5. 风险提示</h3><p>${escape(account.risk_notes||'未填写额外风险提示')}</p><h3>6. 相关协助人</h3>${account.assistants.map(item=>`<p>${escape(item.role)} · ${escape(item.contact_timing)} · ${escape(item.allowed_help)}</p>`).join('')||'<p>未设置协助人</p>'}<h3>7. 个人嘱托</h3><p>${escape(account.personal_message?.text||'未填写')}</p><h3>8. 本账户相关附件</h3>${account.attachment_sections.map(section=>`<h4>${escape(section.label)}</h4>${section.attachments.map(reportAttachment).join('')}`).join('')||'<p>无附件</p>'}<button data-edit-account="${account.account_id}">修改账户</button></section>`).join('')}<section class="card"><h2>附件统计</h2><p>共 ${report.attachment_count} 个附件 · ${new Set(report.attachment_directory.map(file=>file.account_id)).size} 个账户 · ${sections.size} 个章节</p><button id="manage-all-files">管理全部附件</button></section>${report.issues.length?`<section class="card issue"><h2>未完成</h2>${report.issues.map(item=>`<p>${escape(item.business_message)}</p>`).join('')}</section>`:''}<div class="actions"><button class="secondary" id="report-back">返回Dashboard</button><button class="secondary" id="report-review">Review</button><button id="password" ${gate.allowed?'':'disabled'}>设置密码并生成</button></div>`;document.querySelector('#report-back').onclick=()=>nav('dashboard');document.querySelector('#report-review').onclick=()=>nav('review');document.querySelector('#password').onclick=()=>nav('password');document.querySelector('#manage-all-files').onclick=()=>openAttachmentCenter();document.querySelectorAll('[data-manage-file]').forEach(node=>node.onclick=()=>openAttachmentCenter({attachment_id:node.dataset.manageFile}));document.querySelectorAll('[data-edit-account]').forEach(node=>node.onclick=()=>nav('accounts',`accounts:${node.dataset.editAccount}:platform_id`));document.querySelectorAll('[data-view-file]').forEach(node=>node.onclick=()=>{const file=store.attachments[node.dataset.viewFile],url=URL.createObjectURL(new Blob([file.bytes],{type:file.mime_type})),a=document.createElement('a');a.href=url;a.download=file.file_name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}

