function renderLocationsV2(anchor){app.innerHTML=`<h1>位置与查找</h1><p>选择一种清晰的记录方式；统一说明与逐项说明不会重复覆盖。</p>${Object.values(store.accounts).map(account=>{const id=account.account_id,selected=selectedConditions(store,id),coverages=Object.values(store.location_coverages).filter(item=>item.account_id===id),summary=coverages.find(item=>item.mode==='SUMMARY'),covered=new Set(summary?.covered_condition_ids??selected),expanded=locationExpansion.get(id)??new Set(coverages.filter(item=>item.mode==='ITEMIZED').flatMap(item=>item.covered_condition_ids));locationExpansion.set(id,expanded);return`<section class="card" data-anchor="locations:${id}:${selected[0]??'coverage'}"><h2>${escape(accountLabel(account,templates))}</h2><fieldset><legend>统一说明所有恢复条件的位置</legend><p>如果多个恢复资料保存在同一位置，可一次性说明。</p><div class="actions"><button class="secondary" data-select-all="${id}">全选本账户恢复条件</button><button class="secondary" data-clear-all="${id}">全部取消</button></div><p>已覆盖条件</p>${selected.map(condition=>`<label class="choice"><input type="checkbox" data-summary-account="${id}" value="${condition}" ${covered.has(condition)&&!expanded.has(condition)?'checked':''}>${conditionLabel(condition)}</label>`).join('')||'<p>请先在模块2选择恢复条件。</p>'}<label class="field">统一位置说明<textarea data-summary-text="${id}">${escape(summary?.description??'')}</textarea></label></fieldset><button class="secondary" data-toggle-itemized="${id}">分别说明不同恢复条件的位置</button><p>如果不同恢复资料存放在不同位置，可逐项填写。</p><div data-itemized-picker="${id}" class="${expanded.size?'':'hidden'}"><p>选择需要单独说明的条件：</p>${selected.map(condition=>`<label class="choice"><input type="checkbox" data-expand-condition="${id}" value="${condition}" ${expanded.has(condition)?'checked':''}>${conditionLabel(condition)}</label>`).join('')}</div>${selected.filter(condition=>expanded.has(condition)).map(condition=>{const item=coverages.find(value=>value.mode==='ITEMIZED'&&value.covered_condition_ids.includes(condition));return`<fieldset><legend>${conditionLabel(condition)}</legend><label class="field">位置类型<input data-location="${id}" data-condition="${condition}" data-key="location_type" value="${escape(item?.location_type??'')}"></label><label class="field">位置名称<input data-location="${id}" data-condition="${condition}" data-key="location_name" value="${escape(item?.location_name??'')}"></label><label class="field">查找说明<textarea data-location="${id}" data-condition="${condition}" data-key="description">${escape(item?.description??'')}</textarea></label></fieldset>`;}).join('')}${attachmentHint(id,'locations','位置说明',[...covered].filter(condition=>!expanded.has(condition)))}</section>`;}).join('')||`<p>${dependentModuleEmptyPrompt}</p>`}${back()}`;const sync=()=>{try{saveVisibleModule();}catch(error){show(productErrorMessage(error));}};document.querySelectorAll('[data-select-all]').forEach(node=>node.onclick=()=>{const id=node.dataset.selectAll,expanded=locationExpansion.get(id)??new Set();document.querySelectorAll(`[data-summary-account="${id}"]`).forEach(item=>item.checked=!expanded.has(item.value));sync();});document.querySelectorAll('[data-clear-all]').forEach(node=>node.onclick=()=>{document.querySelectorAll(`[data-summary-account="${node.dataset.clearAll}"]`).forEach(item=>item.checked=false);sync();});document.querySelectorAll('[data-toggle-itemized]').forEach(node=>node.onclick=()=>document.querySelector(`[data-itemized-picker="${node.dataset.toggleItemized}"]`).classList.toggle('hidden'));document.querySelectorAll('[data-expand-condition]').forEach(node=>node.onchange=()=>{const id=node.dataset.expandCondition,set=locationExpansion.get(id)??new Set();node.checked?set.add(node.value):set.delete(node.value);locationExpansion.set(id,set);const summary=document.querySelector(`[data-summary-account="${id}"][value="${CSS.escape(node.value)}"]`);if(summary&&node.checked)summary.checked=false;sync();render(anchor);});document.querySelectorAll('[data-summary-account],[data-summary-text],[data-location]').forEach(node=>node.onchange=sync);focus(anchor);}
function renderInstructionsV2(anchor){app.innerHTML=`<h1>恢复与转移步骤</h1><p>文字即时保留在当前页面；点击底部“保存并继续”统一提交两个账户。</p>${Object.values(store.accounts).map(account=>{const item=store.recovery_instructions[account.account_id];return`<fieldset data-anchor="instructions:${account.account_id}:instruction"><legend>${escape(accountLabel(account,templates))}</legend><label class="field">恢复与转移步骤<textarea data-instruction="${account.account_id}" data-key="instruction_text">${escape(item.instruction_text)}</textarea></label><label class="field">风险提示（选填）<textarea data-instruction="${account.account_id}" data-key="optional_risk_notes">${escape(item.optional_risk_notes)}</textarea></label></fieldset>`;}).join('')||`<p>${dependentModuleEmptyPrompt}</p>`}${back()}`;focus(anchor);}
