function renderPurchasePlans(){app.innerHTML=purchaseShell(`<header class="purchase-heading"><p class="eyebrow">LEGAVIK PLANS</p><h1>选择适合您的 Recovery Map 方案</h1><p>一次付费，完成 Recovery Map、加密长期存储与独立恢复准备。</p><small>核心安全与独立恢复能力适用于所有方案。</small></header><div class="plan-grid">${Object.entries(planCatalog).map(([name,plan])=>`<article class="plan-card ${name==='Complete'?'recommended':''}">${name==='Complete'?'<span class="popular">推荐 · MOST POPULAR</span>':''}<h2>${plan.displayName}</h2><p class="plan-price"><span>USD</span><strong>${plan.price}</strong></p><p class="plan-positioning">${plan.description}</p><ul>${plan.features.map(item=>`<li>✓ ${item}</li>`).join('')}</ul><button data-select-plan="${name}">选择${plan.displayName}</button></article>`).join('')}</div><details id="feature-comparison" class="feature-comparison"><summary>查看完整功能比较 <span aria-hidden="true">↓</span></summary><div class="comparison-wrap"><table><thead><tr><th scope="col">服务内容</th><th scope="col">基础版 <small>USD 99</small></th><th scope="col" class="comparison-standard">标准版 <small>USD 199</small></th></tr></thead><tbody>${planComparison.map(([feature,essential,complete])=>`<tr><th scope="row">${feature}</th><td>${essential}</td><td class="comparison-standard">${complete}</td></tr>`).join('')}</tbody></table></div></details>`);document.querySelectorAll('[data-select-plan]').forEach(node=>node.onclick=()=>selectPlan(node.dataset.selectPlan));bindPurchaseInfoLinks();}
