function renderDashboardV5(){const completed=resolvedModules(),complete=completed.size,next=flow.slice(0,6).find(id=>!completed.has(id))??'message';app.innerHTML=`<section class="dashboard-hero"><div><p class="eyebrow">YOUR RECOVERY MAP</p><h1>${escape(store.title)}</h1><p>一步一步整理未来恢复需要的账户、条件和说明。你随时可以返回修改，只有六个模块全部处理后才会创建安全恢复版本。</p><div class="actions"><button id="next-task">${complete===6?'检查并完善':complete?'继续建立恢复地图':'开始建立恢复地图'}</button></div><p class="dashboard-status">${complete===6?'六个模块已完成，可以进入检查与预览。':`已完成 ${complete}/6${complete?` · 下一步：${labels[next]}`:''}`}</p></div><div class="recovery-compass"><div><strong>${complete}/6</strong><span>准备进度</span></div></div></section>${complete?`<div class="overview-secondary-actions"><button class="secondary" id="review">检查待完善内容</button>${complete===6&&receipt.generation_allowed?'<button class="secondary" id="report">预览恢复说明</button>':''}</div>`:''}<div id="message"></div>`;document.querySelector('#next-task').onclick=()=>complete===6?nav('review'):navTo(v3State.introduced?next:'before');document.querySelector('#review')?.addEventListener('click',()=>nav('review'));document.querySelector('#report')?.addEventListener('click',()=>nav('report'));}

