function renderVersionUpdateDashboard(){const changed=versionUpdateHasChanges(),check=changed?versionUpdateGateState():null,ready=Boolean(changed&&check?.gate.allowed);app.innerHTML=`<section class="dashboard-hero version-update-loaded"><div><p class="eyebrow">UPDATE RECOVERY MAP</p><h1>当前版本 V${versionUpdateContext.sourceVersionNumber} 已完整载入</h1><p>您只需要修改发生变化的内容；没有变化的信息无需调整。完成修改后即可创建更新后的 Recovery Map。</p></div></section><section class="card"><h2>修改模块内容</h2><div class="grid version-update-module-grid">${flow.slice(0,6).map((id,index)=>`<button class="version-update-module-button" data-update-module="${id}">${String(index+1).padStart(2,'0')} ${labels[id]}</button>`).join('')}</div></section><details class="card"><summary>如何更新 Recovery Map？</summary><p>选择需要调整的模块，修改发生变化的内容；没有变化的信息无需调整。</p><p>如需调整附件，可以在对应模块内点击“添加附件”，对附件进行新增、替换或删除；也可以点击“管理附件”，统一查看和管理本次更新中的附件。</p><p>完成修改后，点击“更新 Recovery Map”进入下一步。设置或确认 Recovery Password 后，点击“创建更新后的 Recovery Map”即开始安全存储。安全存储开始后，请不要关闭、刷新或返回当前页面，直到系统提示创建完成。</p></details><div class="actions"><button class="secondary" id="manage-update-files">管理附件</button><button id="create-updated-map" ${ready?'':'disabled'}>更新 Recovery Map</button></div><div id="message"></div>`;document.querySelectorAll('[data-update-module]').forEach(node=>node.onclick=()=>navTo(node.dataset.updateModule));document.querySelector('#manage-update-files').onclick=()=>openAttachmentCenter();if(changed&&!ready){const message=document.querySelector('#message');message.className='card error';message.textContent=versionUpdateGateMessages(check).join('；')||'当前修改尚未通过创建前检查，请返回对应模块确认。';}document.querySelector('#create-updated-map').onclick=()=>{const latest=versionUpdateGateState();if(!versionUpdateHasChanges())return show('请先修改至少一项内容或附件。');if(!latest.gate.allowed)return renderVersionUpdateDashboard();navTo('password');};}

