function applyRestoredOperation(record){
  store=record.store;
  receipt=record.receipt;
  artifacts=record.artifacts;
  mainnetEvidence=record.evidence;
  pendingMainnetTransaction=record.signed_transaction??record.signedTransaction??null;
  currentOperation=record.operation;
  const restoredVersionContext=versionOperationContext(currentOperation.operation_id)??versionOperationContext(record.store.draft_id);
  if(restoredVersionContext)versionUpdateContext={...restoredVersionContext,moduleStates:Object.fromEntries(flow.slice(0,6).map(id=>[id,'已检查，无变化'])),changeTypes:[]};
  mainnetQuote=currentOperation.quote??null;
  operationRestoreError=null;
  historyDescriptor=null;
  historyNoticeDismissed=true;
  current='password';
  render(null,{resetScroll:true});
  app.dataset.restoredOperationId=record.operation_id;
  app.dataset.restoredOperationState=record.operation.state;
  app.dataset.restoredDraftId=record.store.draft_id;
}
