function initializeVersionUpdateHandoff(){
  if(!versionUpdateMode)return;
  const channel=queryParams.get('channel'),sourceVersionId=queryParams.get('version_id'),sourceVersionNumber=Number(queryParams.get('version_number'));
  if(!channel||!sourceVersionId||!Number.isInteger(sourceVersionNumber)||!opener){renderVersionUpdateFailure('版本更新入口信息不完整，请返回客户中心后重新进入。');return;}
  let readyTimer=null,timeoutTimer=null;
  const stopHandshake=()=>{clearInterval(readyTimer);clearTimeout(timeoutTimer);removeEventListener('message',receive);};
  const receive=event=>{if(event.origin!==location.origin||event.source!==opener||event.data?.type!=='LEGAVIK_VERSION_UPDATE_SOURCE'||event.data?.channel!==channel)return;try{const snapshot=event.data.snapshot;versionUpdateSourceDiagnostics=event.data.sourceDiagnostics??null;if(queryParams.get('snapshot_id')&&snapshot?.snapshot_id!==queryParams.get('snapshot_id'))throw new Error('恢复材料与所选版本不匹配。');store=createVersionUpdateDraft(snapshot,{draftId:createRecoveryMapDraftId({prefix:'version-update'}),sourceVersionId,sourceVersionNumber});versionUpdateBaselineFingerprint=currentUpdateFingerprint();versionUpdateContext={mapRowId:queryParams.get('map_row_id'),recoveryMapId:queryParams.get('recovery_map_id'),sourceVersionRowId:queryParams.get('version_row_id'),sourceVersionId,sourceVersionNumber,moduleStates:Object.fromEntries(flow.slice(0,6).map(id=>[id,'未检查']))};versionUpdatePassword=typeof event.data.recoveryPassword==='string'?event.data.recoveryPassword:'';v3State={...defaultV3State(),introduced:true,module_resolutions:Object.fromEntries(flow.slice(0,6).map(id=>[id,true]))};current='dashboard';recalc();stopHandshake();render(null,{resetScroll:true});app.dataset.runtimeState='READY';}catch(error){versionUpdatePassword='';stopHandshake();renderVersionUpdateFailure(error.message);}};
  addEventListener('message',receive);const announceReady=()=>opener?.postMessage({type:'LEGAVIK_VERSION_UPDATE_READY',channel},location.origin);announceReady();readyTimer=setInterval(announceReady,400);timeoutTimer=setTimeout(()=>{stopHandshake();renderVersionUpdateFailure('当前版本数据未能完成安全载入，请重新加载或返回客户中心。');},12000);
}
